/**
 * n8n Code node — "Extract Body Blocks"
 * Mode: Run Once for Each Item
 *
 * Pulls offer content out of an EMAIL BODY, as opposed to an attachment.
 *
 * Emits blocks of two shapes, because supplier emails come in both:
 *
 *   table   — a grid, from an HTML <table> or from delimited plain text.
 *             Bluebird, Brockagh, Rio Mare, Fairy, the drinks list.
 *   labels  — vertical "Label: value" pairs describing ONE product.
 *             Marco Polo writes offers this way; there is no table at all.
 *
 * It also returns the surrounding PROSE, which is not decoration. These emails
 * routinely state offer-wide terms in sentences around the grid rather than in
 * columns — "Terms: T2 | EXW Loendersloot", "Lead Time: Approximately 2 weeks",
 * "MOQ 1 pallet/line", "This is ex-works Virginia". A parser that reads only
 * the table silently drops the incoterm, the warehouse and the lead time.
 *
 * Signature blocks are removed first. Brockagh's footer carries a street
 * address and two phone numbers, which is exactly the kind of thing a
 * delimited-text reader will happily treat as a data row.
 */

const item = $input.item.json;

// ── The attachment always wins ──────────────────────────────────────────────
// An email may carry BOTH a spreadsheet and a summary table in the body. The
// spreadsheet is authoritative — it is the full list, while the body is
// usually an excerpt — so the body is not parsed when one is present. Without
// this, the Excel workflow and this one both ingest the same offer.
const SPREADSHEET = /\.(xlsx|xlsm|xltx|xls|csv|tsv)$/i;
const attached = Object.values($input.item.binary || {})
  .map((b) => String(b.fileName || ''))
  .filter((n) => SPREADSHEET.test(n));

if (attached.length) {
  return { json: { ...item, blocksFound: 0, blocks: [], prose: '',
    skipReason: `Spreadsheet attached (${attached.join(', ')}) — the Excel workflow handles this email` } };
}

const html = String(item.bodyHtml || item.html || '');
const plain = String(item.bodyPlain || item.text || item.body || item.snippet || '');

const source = html || plain;
if (!source.trim()) {
  return { json: { ...item, blocksFound: 0, blocks: [], prose: '',
    exceptionReason: 'Email body is empty' } };
}

// ── 1. Trim quoted history and the signature ────────────────────────────────
const asText = html ? htmlToText(html) : plain;
const trimmed = stripSignature(stripQuoted(asText));

// ── 1b. Who actually sent the offer ─────────────────────────────────────────
// Offers arrive FORWARDED into offers@akay.ie, so the envelope sender is
// always the forwarder, not the supplier. Keying profiles on it would match
// one address for every supplier in the business. The real sender sits in the
// forwarded header block.
const forwarded = forwardedSender(asText);
const envelope = extractEmail(item.from || item.fromAddress || '');
const effective = forwarded || envelope;

// ── 2. Tables ───────────────────────────────────────────────────────────────
const blocks = [];

if (html) {
  // Scan only the forwarded portion. Everything before the marker is the
  // forwarder's own message, and an email signature is itself built from
  // <table> for layout — left in, it is extracted as a two-column price list.
  for (const grid of htmlTables(afterForward(html))) {
    if (grid.length >= 2) blocks.push({ type: 'table', rows: grid });
  }
}

// Plain-text grids. Only attempted when HTML yielded nothing, so a well-formed
// HTML table is never also parsed a second time from its text rendering.
if (blocks.length === 0) {
  for (const grid of textTables(trimmed)) {
    if (grid.length >= 2) blocks.push({ type: 'table', rows: grid });
  }
}

// ── 3. Label:value blocks ───────────────────────────────────────────────────
// Only when no table was found. An email with a grid may still contain
// "Lead Time: 2 weeks" lines, and those are offer-wide prose, not a product.
if (blocks.length === 0) {
  const labels = labelValueBlock(trimmed);
  if (labels) blocks.push({ type: 'labels', ...labels });
}

return {
  json: {
    ...item,
    blocksFound: blocks.length,
    blocks,
    // Handed to the profile so offer-wide terms can be lifted from sentences.
    //
    // Grid lines are removed first. Left in, the table's own column headings
    // are read as prose: a "MOQ" heading matches the MOQ rule and captures the
    // rest of the header row ("HS Code / Inner / Outer") as the offer-wide
    // minimum order. Harmless when MOQ is also mapped per row, since the row
    // value wins — silently wrong when it is not.
    prose: proseOnly(trimmed).slice(0, 8000),
    fromAddress: effective,
    senderDomain: (effective.split('@')[1] || ''),
    envelopeFrom: envelope,
    forwardedFrom: forwarded,
    // True when the supplier was recovered from a forwarded header rather than
    // the envelope. Useful when a profile fails to match and someone is
    // working out why.
    senderFromForward: Boolean(forwarded),
    exceptionReason: blocks.length ? null
      : 'No table or label:value block found in the email body',
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/** HTML from the forwarded marker onward, or all of it when not a forward. */
function afterForward(src) {
  const m = src.match(/-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}/i)
         || src.match(/Begin forwarded message:/i);
  return m && m.index !== undefined ? src.slice(m.index) : src;
}

/**
 * A layout table used for a signature, not a price list. Signatures carry
 * contact links and images; offer tables carry neither.
 */
function isSignatureTable(t) {
  return /<img\b/i.test(t) || /href\s*=\s*["']?(?:tel:|mailto:)/i.test(t);
}

/** Rows of cells from every <table> in the HTML. */
function htmlTables(src) {
  const out = [];
  const tables = src.match(/<table[\s\S]*?<\/table>/gi) || [];

  for (const t of tables) {
    if (isSignatureTable(t)) continue;
    const rows = [];
    for (const tr of t.match(/<tr[\s\S]*?<\/tr>/gi) || []) {
      const cells = (tr.match(/<t[dh][\s\S]*?<\/t[dh]>/gi) || []).map(cellText);
      if (cells.some((c) => c !== '')) rows.push(cells);
    }
    if (rows.length) out.push(rows);
  }
  return out;
}

function cellText(cell) {
  return decode(cell.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

/**
 * Grids in plain text. A run of consecutive lines sharing the same delimiter
 * and a consistent column count is treated as one table.
 *
 * Tabs are tried before multi-space, because a tab-delimited line also contains
 * runs of spaces inside product names ("Absolut Blue Original") and splitting
 * on those would shred the row.
 */
function textTables(text) {
  const lines = text.split('\n').map((l) => l.replace(/\s+$/, ''));
  const out = [];
  let current = null;

  for (const line of lines) {
    const cells = splitRow(line);

    if (cells && cells.length >= 2) {
      if (current && current[0].length === cells.length) current.push(cells);
      else { if (current && current.length >= 2) out.push(current); current = [cells]; }
    } else {
      if (current && current.length >= 2) out.push(current);
      current = null;
    }
  }
  if (current && current.length >= 2) out.push(current);
  return out;
}

/**
 * Drop lines that are grid rows, keeping only the sentences around the table.
 * A line that splits into two or more cells is part of the table, not prose.
 */
function proseOnly(text) {
  return text
    .split('\n')
    .filter((line) => {
      const cells = splitRow(line);
      return !(cells && cells.length >= 2);
    })
    .join('\n');
}

function splitRow(line) {
  if (!line.trim()) return null;
  if (line.includes('\t')) return line.split('\t').map((c) => c.trim());

  // Two or more spaces as a column break — how pasted grids usually survive.
  const parts = line.split(/ {2,}/).map((c) => c.trim()).filter(Boolean);
  return parts.length >= 2 ? parts : null;
}

/**
 * "Label: value" lines describing a single product.
 *
 * Returns the labels as a header row and the values as one data row, so the
 * SAME downstream mapping applies — a profile maps a field to a column index
 * either way, and nothing after this node needs to know which shape it was.
 */
function labelValueBlock(text) {
  const labels = [];
  const values = [];
  let title = '';

  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line) continue;

    const m = line.match(/^([A-Za-z][A-Za-z0-9 \/&().'-]{1,40}?)\s*:\s*(.+)$/);
    if (!m) {
      // A line ending in a colon with nothing after it is a heading. Keep the
      // LAST one seen before the pairs begin, not the first: these emails open
      // with a prose lead-in that also ends in a colon ("Please see the
      // following offers for ...:"), and the product heading sits below it,
      // directly above the values it describes.
      if (labels.length === 0 && /:$/.test(line) && line.length > 8) {
        title = line.replace(/:$/, '').trim();
      }
      continue;
    }

    const label = m[1].trim();
    const value = m[2].trim();

    // Contact-detail labels are not product attributes.
    if (/^(tel|fax|mobile|office|email|e-?mail|phone|web|www|http)/i.test(label)) continue;

    labels.push(label);
    values.push(value);
  }

  if (labels.length < 2) return null;

  if (title) { labels.unshift('Product'); values.unshift(title); }
  return { rows: [labels, values], title };
}

/**
 * Separate the message we care about from the surrounding conversation.
 *
 * A FORWARD and a REPLY need opposite treatment, and getting it backwards
 * deletes the offer:
 *
 *   forward — the offer is what follows the marker. Everything BEFORE it is
 *             the forwarder's own signature and covering note, so drop that.
 *   reply   — the offer, if any, is what precedes the marker. Everything
 *             after is the earlier message, so drop that.
 *
 * The previous version treated a bare "From:" line as a reply marker, which
 * cut at the forwarded header and removed the entire forwarded offer.
 */
function stripQuoted(text) {
  const fwd = text.match(/^-{2,}\s*Forwarded message\s*-{2,}\s*$/im)
           || text.match(/^-{2,}\s*Original Message\s*-{2,}\s*$/im)
           || text.match(/^\s*Begin forwarded message:\s*$/im);

  let body = text;
  if (fwd && fwd.index !== undefined) {
    // Skip past the forwarded header block (From/Date/Subject/To lines).
    const after = body.slice(fwd.index + fwd[0].length);
    const headerEnd = after.search(/\n\s*\n/);
    body = headerEnd >= 0 ? after.slice(headerEnd) : after;
  }

  const reply = body.match(/^\s*On .+ wrote:\s*$/m) || body.match(/^_{5,}\s*$/m);
  return reply && reply.index !== undefined ? body.slice(0, reply.index) : body;
}

/**
 * The supplier's address from a forwarded header block. Taken only from the
 * lines directly under the forward marker, so a mailto: elsewhere in the body
 * cannot be mistaken for the sender.
 */
function forwardedSender(text) {
  const fwd = text.match(/^-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}\s*$/im)
           || text.match(/^\s*Begin forwarded message:\s*$/im);
  if (!fwd || fwd.index === undefined) return null;

  const header = text.slice(fwd.index, fwd.index + 600);
  const m = header.match(/^\s*From:\s*.*?([^\s<>"]+@[^\s<>"]+\.[a-z]{2,})/im);
  if (!m) return null;

  const addr = m[1].toLowerCase().replace(/[.,;>]+$/, '');
  // A forward of our own mail is not a supplier.
  return /@akay\.ie$/i.test(addr) ? null : addr;
}

/**
 * Drop the sign-off and everything after it. Supplier footers carry street
 * addresses and phone numbers that a delimited-text reader treats as rows.
 */
function stripSignature(text) {
  const re = /^\s*(kind regards|best regards|regards|many thanks|thanks and regards|br|yours (sincerely|faithfully))\s*[,.]?\s*$/im;
  const m = text.match(re);
  return m && m.index !== undefined ? text.slice(0, m.index) : text;
}

function htmlToText(src) {
  return decode(
    src
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
      .replace(/<\/(p|div|tr|h[1-6]|li)>/gi, '\n')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/t[dh]>/gi, '\t')
      .replace(/<[^>]+>/g, '')
  ).replace(/[ \t]+\n/g, '\n');
}

function decode(s) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', euro: '€', pound: '£' };
  return String(s)
    .replace(/&#(\d+);/g, (_m, d) => String.fromCharCode(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_m, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => named[n.toLowerCase()] ?? m);
}

function extractEmail(raw) {
  const m = String(raw).match(/<([^>]+)>/);
  return (m ? m[1] : String(raw)).trim().toLowerCase();
}

/**
 * n8n Code node — "Resolve Body Profile"
 * Mode: Run Once for Each Item
 *
 * Picks the Sheet Profile for an email offer, and lifts offer-wide terms out
 * of the surrounding prose.
 *
 * KEYED ON SENDER, NOT ON A HEADER FINGERPRINT.
 * Spreadsheet profiles fingerprint the header row, which works because the file
 * is machine-generated and the header is stable. Email tables are typed by hand
 * into Outlook: of six real supplier emails, one had no product-name header,
 * one had a blank price header, one was three stacked tables and one had no
 * table at all. There is nothing dependable to fingerprint. The supplier is the
 * stable thing, so that is the key.
 *
 * This also sidesteps the price-column gate. A sender-keyed profile states that
 * the price is column 3 because it is Brockagh — no header word required.
 *
 * TERMS IN PROSE.
 * These emails put per-offer terms in sentences rather than columns:
 *   "Terms: T2 | EXW Loendersloot"
 *   "This is ex-works Virginia."
 *   "Prices EXW in EUR - Zielona Góra, Poland"
 *   "Lead Time: Approximately 2 weeks"
 * Reading only the grid silently drops the incoterm, warehouse and lead time,
 * so the prose is parsed and merged UNDER the profile's own defaults — an
 * explicit profile setting always wins over something inferred from a sentence.
 */

const WAREHOUSES = ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
                    'Greece', 'Indonesia', 'Czech', 'NewCorp', 'Vergèze', 'Bergamo'];
const INCOTERMS = ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP'];

const item = $input.item.json;

// Airtable search results for Sheet Profiles where Profile Type is an email type.
const candidates = (item.profileCandidates || []).map((p) => p.fields || p);

const from = String(item.fromAddress || '').toLowerCase();
const domain = String(item.senderDomain || '').toLowerCase();

// Exact address beats domain: a supplier may have one contact who sends a
// different layout from the rest of the office.
let chosen = candidates.find((p) => match(p['Sender Match']) === from)
          || candidates.find((p) => match(p['Sender Match']) === domain);

const prose = parseProse(String(item.prose || ''));

if (!chosen) {
  return {
    json: {
      ...item,
      profileFound: false,
      proseTerms: prose.terms,
      proseNotes: prose.notes,
      exceptionReason:
        `No email profile for ${from || '(unknown sender)'}` +
        `${domain ? ` or domain ${domain}` : ''} — routed for manual mapping`,
    },
  };
}

// ── Ingestion gate ──────────────────────────────────────────────────────────
// Two separate reasons to skip, deliberately kept apart:
//   Supplier Status Blacklisted/Inactive/Archived — we do not trade with them
//   Skip Offer Ingestion ticked — we do trade, but their prices are routinely
//                                 too high for parsing to be worth it
//
// Neither deletes or hides anything. The email is left exactly as it is and
// simply not ingested, so a person can still read it, and unticking the box
// makes the next offer parse normally.
const supplierStatus = firstName(chosen['Supplier Status']);
const supplierSkip = firstBool(chosen['Supplier Skip']);
const BLOCKING = ['Blacklisted', 'Inactive', 'Archived'];

if (supplierSkip || BLOCKING.includes(supplierStatus)) {
  return {
    json: {
      ...item,
      profileFound: true,
      skipIngestion: true,
      profileName: chosen['Profile Name'],
      skipReason: supplierSkip
        ? `${chosen['Profile Name']}: Skip Offer Ingestion is ticked on the supplier — offers not parsed on price grounds`
        : `${chosen['Profile Name']}: supplier Status is ${supplierStatus} — offers not parsed`,
    },
  };
}

let columnMap = {};
let profileDefaults = {};
try { columnMap = JSON.parse(chosen['Column Map'] || '{}'); } catch (e) { /* reported below */ }
try { profileDefaults = JSON.parse(chosen['Defaults'] || '{}'); } catch (e) { /* reported below */ }

// A Column Map may address columns by INDEX or by LABEL NAME. Label names are
// the right choice for Label:value profiles — the position of "Price" depends
// on which other labels the supplier happened to include that day, so a single
// added line would shift every index. Names are resolved against the extracted
// header here, so everything downstream still sees plain indices.
const headerCells = (item.headerCells || []).map((h) => String(h ?? '').trim().toLowerCase());
if (headerCells.length) {
  const resolved = {};
  const unresolved = [];
  for (const [field, ref] of Object.entries(columnMap)) {
    if (Number.isInteger(ref)) { resolved[field] = ref; continue; }
    const idx = headerCells.indexOf(String(ref).trim().toLowerCase());
    if (idx >= 0) resolved[field] = idx;
    else unresolved.push(`${field} -> "${ref}"`);
  }
  columnMap = resolved;
  if (unresolved.length) {
    return { json: { ...item, profileFound: false, proseTerms: prose.terms,
      exceptionReason:
        `Profile "${chosen['Profile Name']}" references labels absent from this email: ` +
        `${unresolved.join(', ')}. Labels present: ${headerCells.filter(Boolean).join(', ')}` } };
  }
}

if (!Object.keys(columnMap).length) {
  return { json: { ...item, profileFound: false,
    exceptionReason: `Profile "${chosen['Profile Name']}" has an unreadable Column Map` } };
}

return {
  json: {
    ...item,
    profileFound: true,
    profileName: chosen['Profile Name'],
    profileType: name(chosen['Profile Type']),

    // The profile's linked Supplier, forwarded so 04 can link the offer and
    // read the trust level. Without this the email path created every offer
    // with no Supplier at all — the fields all looked right and nothing said
    // who to buy from.
    supplierRecordId: linkId(chosen['Supplier']),
    supplierName: linkName(chosen['Supplier']),
    // High auto-approves the PUBLIC LISTING only. The send to clients still
    // waits for a person, on every supplier.
    supplierTrust: firstName(chosen['Supplier Trust']),

    columnMap,
    // Prose terms fill gaps the profile leaves; they never override it.
    profileDefaults: { ...prose.terms, ...profileDefaults },
    proseTerms: prose.terms,
    proseNotes: prose.notes,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

function match(v) { return String(v ?? '').trim().toLowerCase(); }
function name(v) { return v && typeof v === 'object' ? v.name : v; }

/** Airtable lookups always return arrays, even for a single linked record. */
function firstName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return a && typeof a === 'object' ? a.name : (a ?? null);
}
function firstBool(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return Boolean(a);
}

/**
 * A linked-record field, which Airtable returns as bare record-ID strings over
 * the REST API but as { id, name } objects through some clients. Both shapes
 * are handled so the supplier link survives either.
 */
function linkId(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (!a) return null;
  return typeof a === 'object' ? (a.id || null) : String(a);
}
function linkName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return a && typeof a === 'object' ? (a.name || null) : null;
}

/**
 * Pull offer-wide terms out of the prose around the table.
 *
 * Deliberately conservative: a term is only taken when its wording is
 * unambiguous. Anything recognised but unmappable is reported in `notes` for a
 * human rather than guessed into a field.
 */
function parseProse(text) {
  const terms = {};
  const notes = [];
  const t = text.replace(/\s+/g, ' ');

  // Incoterm — "EXW Loendersloot", "ex-works Virginia", "DAP Holland"
  const inco = t.match(/\b(ex[\s-]?works?|exw|fca|fob|cfr|cif|dap|ddp)\b/i);
  if (inco) {
    const raw = inco[1].toLowerCase().replace(/[\s-]/g, '');
    terms.incoterm = /^ex(works?)?$/.test(raw) ? 'EXW' : inco[1].toUpperCase();
  }

  // Warehouse — matched against the Airtable option list only.
  for (const w of WAREHOUSES) {
    if (new RegExp(`\\b${escapeRe(w)}\\b`, 'i').test(t)) { terms.warehouse = w; break; }
  }

  // A location was clearly stated but is not one of our warehouses. Reported
  // rather than forced to "Other", because the name matters to a human:
  // "ex-works Virginia" is Virginia in Co. Cavan, not the US state, and
  // guessing wrong puts the goods on another continent.
  if (!terms.warehouse && inco) {
    const after = t.slice(inco.index + inco[0].length).match(/^\s*[:\-]?\s*([A-ZÀ-Ý][\w'’-]*(?:\s+[A-ZÀ-Ý][\w'’-]*){0,3})/);
    if (after) notes.push(`Stated location "${after[1].trim()}" is not a known warehouse — set it by hand`);
  }

  // Bond / customs status
  if (/\bT1\b/.test(t)) terms.bondStatus = 'T1';
  else if (/\bT2\b/.test(t)) terms.bondStatus = 'T2';
  else if (/\bduty[\s-]?paid\b/i.test(t)) terms.bondStatus = 'Duty Paid';
  else if (/\b(under )?bond(ed)?\b/i.test(t)) terms.bondStatus = 'Bonded';

  // Currency stated in prose — "Prices EXW in EUR"
  const cur = t.match(/\bprices?\b[^.]{0,40}?\b(eur|euro|usd|gbp|aed|sgd)\b/i);
  if (cur) terms.currency = cur[1].toUpperCase().replace('EURO', 'EUR');

  // Lead time and MOQ are matched PER LINE, and stopped at the next known
  // keyword. Flattened whole-text matching runs straight past the end of the
  // value: one real email reads "Lead time 2 weeks / MOQ 1 pallet per line /
  // Price is EXW Athens" on consecutive lines, and a greedy match captured all
  // three as the lead time.
  const STOP = /\b(moq|lead\s*time|price|prices|terms|warehouse|incoterm|delivery|payment)\b/i;

  for (const line of text.split('\n').map((l) => l.trim()).filter(Boolean)) {
    if (!terms.leadTime) {
      const lead = line.match(/lead[\s-]?time\s*[:\-]?\s*(?:approx(?:imately)?\.?\s*)?(.+)$/i);
      if (lead) terms.leadTime = clip(lead[1], STOP);
    }
    if (!terms.moq) {
      const moq = line.match(/\bmoq\b\s*[:\-]?\s*(.+)$/i);
      if (moq) terms.moq = clip(moq[1], STOP);
    }
  }

  return { terms, notes };
}

/** Trim a captured value at the next keyword, sentence end or pipe. */
function clip(value, stop) {
  let v = String(value).split(/[.|]/)[0].trim();
  const m = v.match(stop);
  if (m && m.index > 0) v = v.slice(0, m.index).trim();
  return v.replace(/[,;\/\s]+$/, '').slice(0, 60);
}

function escapeRe(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/**
 * n8n Code node — "Normalize Rows"
 * Mode: Run Once for Each Item
 *
 * Applies a Sheet Profile's column map to the raw data rows and coerces every
 * value into something the Airtable Offers table will actually accept.
 *
 * This node writes NO approval fields. Ingested offers land as
 * "Awaiting Approval" and are gated by the existing human sign-off.
 */

// ── Airtable single-select options (base appaDSdZkAE9PGkjT, table Offers) ────
// Airtable rejects writes containing an unknown option, so every free-text
// value is coerced into one of these or dropped to a flagged exception.
const OPTIONS = {
  currency: ['EUR', 'USD', 'GBP', 'AED', 'SGD', 'Other'],
  unitType: ['Bottle', 'Can', 'Jar', 'Pack', 'Piece', 'Other'],
  priceType: ['Per Case', 'Per Bottle', 'Per Can', 'Per Piece', 'Per Pack', 'Per Jar'],
  bond: ['Bonded', 'T1', 'T2', 'Duty Paid', 'On Floor', 'Other'],
  incoterm: ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP', 'Other'],
  warehouse: ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
              'Greece', 'Indonesia', 'Czech', 'Other', 'NewCorp', 'Vergèze', 'Bergamo'],
  // Offers.Category has no "Wine" option — it was renamed to "Champagne" on
  // 2026-07-29, since still wine is not a category Akay trades in volume.
  // Everything vinous therefore lands in Champagne, sparkling or not.
  // NOTE: Products.Category still carries BOTH Wine and Champagne. That does
  // not affect product matching, whose key is Brand + Name + Volume +
  // Bond/Customs Status and does not include category.
  category: ['Beer', 'Spirits', 'Champagne', 'Grocery', 'Confectionery',
             'Toiletries', 'Soft Drinks', 'Other FMCG'],
};

// Declared here rather than beside parseVolume: the row loop runs before the
// helper block, and `const` does not hoist the way a function declaration does.
const VOLUME_UNIT_FACTOR = { ml: 1, cc: 1, cl: 10, dl: 100, l: 1000, ltr: 1000, litre: 1000 };

// Same reason as above. parseDate calls this from inside the row loop, which
// runs before the helper block below is evaluated. Latent until a profile
// mapped a BBD column — none of the first five did, so it never fired.
const pad = (v) => String(v).padStart(2, '0');

const SYNONYMS = {
  currency: {
    '€': 'EUR', eur: 'EUR', euro: 'EUR', euros: 'EUR',
    $: 'USD', usd: 'USD', dollar: 'USD', usdollar: 'USD',
    '£': 'GBP', gbp: 'GBP', pound: 'GBP', sterling: 'GBP',
    aed: 'AED', dirham: 'AED', sgd: 'SGD',
  },
  bond: {
    bond: 'Bonded', bonded: 'Bonded', underbond: 'Bonded', inbond: 'Bonded',
    t1: 'T1', t2: 'T2', export: 'T1', eu: 'T2', community: 'T2',
    dutypaid: 'Duty Paid', dp: 'Duty Paid', taxpaid: 'Duty Paid',
    onfloor: 'On Floor', floor: 'On Floor', exstock: 'On Floor',
  },
  unitType: {
    bottle: 'Bottle', btl: 'Bottle', flasche: 'Bottle', bouteille: 'Bottle',
    can: 'Can', cans: 'Can', tin: 'Can',
    jar: 'Jar', pack: 'Pack', pouch: 'Pack', piece: 'Piece', pcs: 'Piece', unit: 'Piece',
  },
  category: {
    beer: 'Beer', lager: 'Beer', ale: 'Beer', cider: 'Beer',
    spirit: 'Spirits', spirits: 'Spirits', whisky: 'Spirits', whiskey: 'Spirits',
    vodka: 'Spirits', gin: 'Spirits', rum: 'Spirits', liqueur: 'Spirits',
    cognac: 'Spirits', brandy: 'Spirits', tequila: 'Spirits',
    champagne: 'Champagne', wine: 'Champagne', wines: 'Champagne',
    prosecco: 'Champagne', sparkling: 'Champagne', cava: 'Champagne', bordeaux: 'Champagne',
    softdrink: 'Soft Drinks', softdrinks: 'Soft Drinks', water: 'Soft Drinks',
    juice: 'Soft Drinks', energy: 'Soft Drinks', soda: 'Soft Drinks',
    grocery: 'Grocery', food: 'Grocery',
    confectionery: 'Confectionery', chocolate: 'Confectionery', sweets: 'Confectionery',
    candy: 'Confectionery', biscuit: 'Confectionery',
    toiletries: 'Toiletries', cosmetics: 'Toiletries', personalcare: 'Toiletries',
  },
};

const item = $input.item.json;
const map = item.columnMap || {};       // { targetField: headerCellIndex }
const defaults = item.profileDefaults || {}; // supplier-level fallbacks
const headers = item.headerCells || [];

const offers = [];

// Seeded with anything the extractor already rejected before reaching here.
// The WhatsApp path refuses some lines outright — a price range, an average —
// and those reasons are far more useful than the "unparseable price" this node
// would produce from the same text. Empty on the spreadsheet and email paths.
const exceptions = (item.preParseExceptions || []).map((e) => ({
  sheetRow: e.sheetRow ?? null,
  productName: e.productName || '',
  sourceSheet: `${item.fileName} :: ${item.sheetName}`,
  exceptionReason: e.exceptionReason,
}));

(item.dataRows || []).forEach((row, i) => {
  const sheetRow = (item.headerRowIndex ?? 0) + 2 + i; // 1-based, as seen in Excel
  const get = (field) => {
    const idx = map[field];
    if (idx === undefined || idx === null) return '';
    return String(row[idx] ?? '').trim();
  };

  const productName = get('productName');
  const rawPrice = get('buyPrice');

  // A row without a product name or a price is a spacer, subtotal or footer.
  // Skipping silently is correct here — these are not failures.
  if (!productName && !rawPrice) return;

  const problems = [];

  // Email price cells carry their own currency and per-unit basis; spreadsheet
  // cells are bare numbers and fall back to the profile for both.
  const price = parsePriceCell(rawPrice);
  if (!productName) problems.push('missing product name');
  if (price.value === null) problems.push(`unparseable price "${rawPrice}"`);
  else if (price.ambiguous) problems.push(`ambiguous decimal separator in "${rawPrice}"`);

  // Pack notation lives in its own column on some sheets and inside the
  // product name on others ("Poliakov 6/70cl", "Absolut 120x5cl").
  const pack = parsePack(get('packFormat') || get('volumeMl') || productName);

  const volume = parseVolume(get('volumeMl'), defaults.volumeUnit)
    ?? pack.volumeMl
    ?? parseVolume(productName, defaults.volumeUnit);
  const pcsCase = parseNumber(get('pcsCase')).value ?? pack.pcsCase;
  const abv = parseAbv(get('abv')) ?? pack.abv ?? parseAbv(productName);
  const weightKg = pack.weightG !== null ? pack.weightG / 1000 : null;

  const bond = coerce('bond', get('bondStatus') || defaults.bondStatus);
  const currency = price.currency || coerce('currency', get('currency') || defaults.currency);
  if (!currency) problems.push('no currency on row or profile default');

  const brand = get('brand') || guessBrand(productName);

  const record = {
    sheetRow,
    sourceSheet: `${item.fileName} :: ${item.sheetName}`,
    sourceMessageId: item.sourceMessageId,

    brand,
    productName,
    variant: get('variant') || '',
    category: coerce('category', get('category') || defaults.category),
    volumeMl: volume,
    pcsCase: pcsCase ?? defaults.pcsCase ?? null,
    unitType: coerce('unitType', get('unitType') || defaults.unitType) || 'Bottle',
    abv,
    originCountry: get('originCountry') || defaults.originCountry || '',
    bondStatus: bond,
    buyPrice: price.value,
    currency,
    // A basis stated in the price cell always wins — it is per row, whereas
    // the profile default is per supplier.
    priceType: price.basis
      || coerce('priceType', get('priceType') || defaults.priceType)
      || 'Per Case',
    priceBasisStated: Boolean(price.basis),
    weightKg,
    stockCases: toCases(parseNumber(get('stockCases')).value, pcsCase, defaults.stockUnit),
    casesPerPallet: parseNumber(get('casesPerPallet')).value,
    piecesPerPallet: parseNumber(get('piecesPerPallet')).value,
    language: get('language') || '',
    moq: get('moq') || '',
    leadTime: get('leadTime') || '',
    eanUnit: cleanEan(get('eanUnit')),
    eanCase: cleanEan(get('eanCase')),
    bbd: parseDate(get('bbd')),
    incoterm: coerce('incoterm', get('incoterm') || defaults.incoterm),
    warehouse: coerce('warehouse', get('warehouse') || defaults.warehouse),

    // Identity key per the Product Matching policy:
    // Brand + Name + Volume + Bond/Customs Status
    productKey: buildProductKey(brand, productName, volume, bond),
  };

  if (problems.length) {
    exceptions.push({ ...record, exceptionReason: problems.join('; ') });
  } else {
    offers.push(record);
  }
});

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    sourceMessageId: item.sourceMessageId,
    fromAddress: item.fromAddress,
    supplierRecordId: item.supplierRecordId || null,
    // Carried through explicitly. 04 reads both, and this node sits between the
    // supplier lookup and 04 on all three ingestion paths — dropping them here
    // silently costs every offer its supplier-specific validity (falling back to
    // 14 days) and leaves the supplier off the internal Offer Name.
    supplierName: item.supplierName || null,
    supplierValidityDays: item.supplierValidityDays ?? null,
    // Drives auto-approval of the PUBLIC LISTING in 04. Not the send approval,
    // which no automated path writes.
    supplierTrust: item.supplierTrust || null,
    profileId: item.profileId || null,
    fingerprint: item.fingerprint,
    parsedCount: offers.length,
    exceptionCount: exceptions.length,
    offers,
    exceptions,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a number written by any European or Anglophone supplier.
 * The dangerous case is "1,234" — either 1234 or 1.234 depending on locale.
 * Rule: when both separators appear, the rightmost is the decimal point.
 * When only a comma appears with exactly 3 trailing digits, it is ambiguous
 * and is flagged rather than guessed, because guessing wrong is a 1000x
 * price error that would reach a client.
 */
function parseNumber(raw) {
  if (raw === null || raw === undefined) return { value: null, ambiguous: false };
  let s = String(raw).trim();
  if (!s) return { value: null, ambiguous: false };

  // Longest form first: stripping "eur" out of "Euro" would leave a stray "o"
  // and the letter check below would then reject an otherwise valid price.
  // Premium Brands writes a literal "Euro" column, so this is not hypothetical
  // — it only escaped notice because that sheet keeps it in its own column.
  s = s.replace(/euros?|dollars?|pounds?|usd|gbp|aed|sgd|eur|[€$£\s]/gi, '').trim();
  if (!s) return { value: null, ambiguous: false };

  // Anything with letters left is prose, not a price — a comment column such as
  // "200 MORE 31ST JULY" or "750 DUE 31ST JULY". Stripping to digits would yield
  // 20031 and 75031 and quote them as prices, so reject outright. This is the
  // main defence when a column map is misaligned against a shifted section.
  if (/[a-z]/i.test(s)) return { value: null, ambiguous: false };

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');
  let ambiguous = false;

  if (hasDot && hasComma) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (hasComma) {
    const after = s.split(',')[1] ?? '';
    if (s.split(',').length > 2) s = s.replace(/,/g, '');       // 1,234,567
    else if (after.length === 3) ambiguous = true;               // 1,234 — unresolvable
    else s = s.replace(',', '.');                                // 12,50
    if (ambiguous) s = s.replace(',', '.');                      // best guess, flagged
  }

  const cleaned = s.replace(/[^0-9.\-]/g, '');
  // Text like "n/a", "TBC" or "POA" strips down to nothing, and Number('') is 0
  // — which would price the row at zero. Reject rather than return a free product.
  if (!/\d/.test(cleaned)) return { value: null, ambiguous: false };

  const n = Number(cleaned);
  return Number.isFinite(n) ? { value: n, ambiguous } : { value: null, ambiguous: false };
}

/**
 * Read a price cell that carries its own currency and per-unit basis.
 *
 * Spreadsheets keep these in separate columns, so the profile can state them
 * once. Email offers write them inline, and the BASIS VARIES ROW BY ROW —
 * one real offer lists "Euro 2,5/btl" directly above "Euro 48,7/cs". Taking
 * the basis from the profile there would be a 6-12x error on half the rows.
 *
 * Returns { value, currency, basis } with currency and basis null when the
 * cell does not state them, so the profile default still applies.
 */
function parsePriceCell(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return { value: null, currency: null, basis: null, ambiguous: false };

  let currency = null;
  if (/€|\beur(o|os)?\b/i.test(s)) currency = 'EUR';
  else if (/£|\bgbp\b|\bpounds?\b/i.test(s)) currency = 'GBP';
  else if (/\$|\busd\b|\bdollars?\b/i.test(s)) currency = 'USD';
  else if (/\baed\b/i.test(s)) currency = 'AED';
  else if (/\bsgd\b/i.test(s)) currency = 'SGD';

  // Trailing "/btl", "/cs", "/case", "/pc" and friends.
  let basis = null;
  const m = s.match(/\/\s*(btl|bottle|cs|case|ctn|carton|pc|pcs|piece|pack|can|jar|unit)\b/i);
  if (m) {
    const k = m[1].toLowerCase();
    if (/^(cs|case|ctn|carton)$/.test(k)) basis = 'Per Case';
    else if (/^(btl|bottle)$/.test(k)) basis = 'Per Bottle';
    else if (/^(pc|pcs|piece|unit)$/.test(k)) basis = 'Per Piece';
    else if (k === 'pack') basis = 'Per Pack';
    else if (k === 'can') basis = 'Per Can';
    else if (k === 'jar') basis = 'Per Jar';
  }

  // Strip the basis suffix before reading the number, or "/btl" leaves letters
  // behind and the prose guard rejects a perfectly good price.
  const numeric = parseNumber(s.replace(/\/\s*[a-z]+\b/gi, ''));

  return { value: numeric.value, currency, basis, ambiguous: numeric.ambiguous };
}

/**
 * Read a trade pack notation into its parts.
 *
 * Four notations appear across real supplier emails:
 *   "6/70cl"          6 bottles x 70cl
 *   "120x5cl"         120 miniatures x 5cl
 *   "12/1000/40"      12 x 1000(ml) x 40% abv
 *   "20 x 250g"       20 units x 250g   (weight, not volume)
 *
 * THE MIDDLE NUMBER'S UNIT IS AMBIGUOUS in the bare "12/1000/40" form: 1000
 * means millilitres, while "6/100/35" means 100 CENTILITRES — both are 1 litre.
 * Resolved by magnitude, since 1000cl would be a ten-litre bottle and 100ml
 * would be a miniature sold by the case of six. The cut-off sits at 200.
 */
function parsePack(raw) {
  const s = String(raw ?? '').trim();
  const out = { pcsCase: null, volumeMl: null, abv: null, weightG: null };
  if (!s) return out;

  // Weight-based: "20 x 250g"
  let m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(g|gr|gram|kg)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    const n = Number(m[2].replace(',', '.'));
    out.weightG = /^kg$/i.test(m[3]) ? n * 1000 : n;
    return out;
  }

  // Explicit volume unit: "6/70cl", "120x5cl", "24/20/13.5%"
  m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    out.volumeMl = parseVolume(`${m[2]}${m[3]}`);
    const abv = s.match(/(\d+(?:[.,]\d+)?)\s*%/);
    if (abv) out.abv = Number(abv[1].replace(',', '.'));
    return out;
  }

  // Bare numeric triple: "12/1000/40", "6/100/35"
  m = s.match(/(\d+)\s*\/\s*(\d+(?:[.,]\d+)?)\s*(?:\/\s*(\d+(?:[.,]\d+)?))?/);
  if (m) {
    out.pcsCase = Number(m[1]);
    const mid = Number(m[2].replace(',', '.'));
    out.volumeMl = mid >= 200 ? Math.round(mid) : Math.round(mid * 10);
    if (m[3]) {
      const a = Number(m[3].replace(',', '.'));
      if (a > 0 && a <= 100) out.abv = a;
    }
  }
  return out;
}

/**
 * Normalise any volume expression to millilitres.
 *
 * `unitHint` comes from the Sheet Profile and is what the column means when the
 * cell carries a bare number. This is not optional detail: one supplier's
 * "content" column reads 70 for a 70cl bottle while another's "ML/BTL" reads
 * 1000 for the same size of bottle. Guessing from magnitude alone turns a 70cl
 * bottle into 70ml.
 */
function parseVolume(raw, unitHint) {
  const s = String(raw ?? '').toLowerCase();
  if (!s) return null;

  let m = s.match(/(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr|litre|liter|cc)\b/);
  if (!m) {
    const bare = parseNumber(s).value;
    if (bare === null) return null;

    const factor = VOLUME_UNIT_FACTOR[String(unitHint || '').toLowerCase()];
    if (factor) return Math.round(bare * factor);

    // No hint: a bare number is millilitres unless it is implausibly small,
    // in which case it is almost certainly litres.
    return bare > 0 && bare < 10 ? Math.round(bare * 1000) : Math.round(bare);
  }

  const n = Number(m[1].replace(',', '.'));
  switch (m[2]) {
    case 'ml': case 'cc': return Math.round(n);
    case 'cl': return Math.round(n * 10);
    case 'dl': return Math.round(n * 100);
    default: return Math.round(n * 1000); // l / ltr / litre / liter
  }
}

/**
 * Airtable stores stock in CASES, so every profile is normalised to cases
 * regardless of what its source column holds — the unit must be consistent
 * across suppliers or the numbers cannot be compared to each other.
 *
 * `stockUnit` is declared per profile: FMCG lists quote stock in pieces
 * (Rexona "Quantity" 18046, ROEM "Stock / pcs" 520), drinks lists in cases.
 *
 * Floored, because a part case is not sellable. Returns null when the source is
 * in pieces but the pack size is unknown — an unconverted piece count sitting
 * in a field labelled "cases" reads as far more stock than exists.
 */
function toCases(value, pcsCase, stockUnit) {
  if (value === null || value === undefined) return null;
  if (String(stockUnit || '').toLowerCase() !== 'pcs') return value;
  if (!pcsCase || pcsCase <= 0) return null;
  return Math.floor(value / pcsCase);
}

function parseAbv(raw) {
  const s = String(raw ?? '');
  const m = s.match(/(\d+(?:[.,]\d+)?)\s*%/) || s.match(/^(\d+(?:[.,]\d+)?)$/);
  if (!m) return null;
  const n = Number(m[1].replace(',', '.'));
  return n > 0 && n <= 100 ? n : null;
}

/**
 * Dates arrive as JS Date (cellDates), Excel serial numbers, or text.
 * Text is read day-first — these are European supplier sheets — but a value
 * that can only be month-first (e.g. 03/25/2026) is still handled.
 */
function parseDate(raw) {
  if (!raw) return null;
  if (raw instanceof Date && !isNaN(raw)) return raw.toISOString().slice(0, 10);

  const s = String(raw).trim();
  if (!s) return null;

  if (/^\d{5}$/.test(s)) {
    const ms = (Number(s) - 25569) * 86400 * 1000; // Excel epoch → Unix
    return new Date(ms).toISOString().slice(0, 10);
  }

  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;

  // "Feb 2027" / "February 2027" — a best-before month with no day. The first
  // of the month is the conservative reading: it expires no later than stated.
  m = s.match(/^([a-z]{3,9})\.?\s+(\d{4})$/i);
  if (m) {
    const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    const idx = months.indexOf(m[1].slice(0, 3).toLowerCase());
    if (idx >= 0) return `${m[2]}-${pad(idx + 1)}-01`;
  }

  // "04/2028" — month and year only, no day. Extremely common on WhatsApp and
  // in email bodies ("bbd 04/2028", "BBD 05/2027"). Read as the first of the
  // month for the same reason as the "Feb 2027" case above: it is the
  // conservative end of the range the supplier actually stated.
  m = s.match(/^(\d{1,2})[\/.\-](\d{4})$/);
  if (m && Number(m[1]) >= 1 && Number(m[1]) <= 12) return `${m[2]}-${pad(m[1])}-01`;

  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
  if (m) {
    let [, a, b, y] = m;
    if (y.length === 2) y = '20' + y;
    const dayFirst = Number(a) > 12 || Number(b) <= 12;
    const day = dayFirst ? a : b;
    const month = dayFirst ? b : a;
    return `${y}-${pad(month)}-${pad(day)}`;
  }

  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
}

function coerce(kind, raw) {
  const s = String(raw ?? '').trim();
  if (!s) return null;

  const exact = OPTIONS[kind].find((o) => o.toLowerCase() === s.toLowerCase());
  if (exact) return exact;

  const key = s.toLowerCase().replace(/[^a-z0-9€$£]/g, '');
  const syn = (SYNONYMS[kind] || {})[key];
  if (syn) return syn;

  for (const [k, v] of Object.entries(SYNONYMS[kind] || {})) {
    if (key.includes(k)) return v;
  }

  return OPTIONS[kind].includes('Other') ? 'Other' : null;
}

function cleanEan(raw) {
  const digits = String(raw ?? '').replace(/\D/g, '');
  return /^\d{8}$|^\d{12,14}$/.test(digits) ? digits : '';
}

/** Fallback when the sheet has no brand column: first word of the product name. */
function guessBrand(name) {
  const first = String(name).trim().split(/\s+/)[0] || '';
  return first.length > 1 ? first : '';
}

function buildProductKey(brand, name, volumeMl, bond) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(brand), n(name), volumeMl ?? '', n(bond)].join('|');
}

/**
 * n8n Code node — "Build Airtable Payload"
 * Mode: Run Once for Each Item
 *
 * Turns normalised rows into Airtable Offers records, splitting matched from
 * unmatched products.
 *
 * Two invariants this node exists to enforce:
 *
 * 1. EVERY offer carries Offer Date + Auto Expiry Days.
 *    Is Expired = IF(TODAY() > {Auto Expiry Date}, "Yes", "No"). Airtable treats
 *    a blank date as earlier than today, so an offer written without expiry data
 *    computes as expired, fails Send Eligible, and sits in the base looking
 *    healthy while never dispatching. Silent, so it is enforced here.
 *
 * 2. INGESTION NEVER SATISFIES A HUMAN APPROVAL.
 *    Since 2026-08-04 human control lives in exactly two places, and this node
 *    writes NEITHER: Listing Approved (the tick by Anil or Annika that puts an
 *    offer on offers.akay.ie) and dispatch approval (Gate 2, Anil or Annika,
 *    per specific dispatch). Otherwise a parser's reading of a price becomes a
 *    quote on the site or in a client's inbox with nobody having looked at it.
 *
 *    Offer Approval Status is a PROCESSING status (Anil, 2026-08-04): Trust
 *    Score High, Medium or Low all write Approved on ingestion; only Trust =
 *    Hold or an unknown/unresolved supplier holds the offer at Awaiting
 *    Approval. It feeds Send Eligible and the Public Listing formula but is no
 *    longer a human control point. (Replaces the 2026-07-30 High-only rule.)
 */

const FALLBACK_VALIDITY_DAYS = 14;

// Declared up here, not beside buildProductIndex which uses it: `const` does not
// hoist, and buildProductIndex is called from the top of the node body, before
// the helper block below has been evaluated. Latent until the Products lookup
// returned anything — with an empty list the loop never runs and never touches
// this — so it would have thrown on the first real file rather than in testing.
const norm = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

// Formula and lookup fields — writing to any of these errors the batch.
const READ_ONLY = new Set([
  'Sell Price', 'Pack Format', 'Is Expired', 'Auto Expiry Date', 'Send Eligible',
  'Public Listing', 'Public Product Description', 'Public Spec', 'Price Display',
  'Public Terms', 'Stock Display', 'whatsapp link',
  'Supplier Name', 'Supplier Email', 'Supplier Country',
  'Supplier Trust Level', 'Supplier Payment Terms',
]);

const item = $input.item.json;

const today = new Date().toISOString().slice(0, 10);
const validityDays = Number(item.supplierValidityDays) > 0
  ? Number(item.supplierValidityDays)
  : FALLBACK_VALIDITY_DAYS;

// An Airtable node REPLACES the items flowing through it rather than adding to
// them, so a product lookup wired in-line does not arrive as a field on this
// item. Reading the node by name is the reliable form; the item field is kept
// as a fallback for the case where an upstream Code node did merge it in.
// Without this the index is empty, every product "fails" to match and a whole
// file lands in review looking like a catalogue problem.
const productIndex = buildProductIndex(
  item.productLookup || nodeRecords('Fetch Products')
);

// Trust-driven approval on ingestion (Anil, 2026-08-04): High, Medium AND Low
// all auto-approve. Only Trust = Hold, or an unknown/unresolved supplier
// (blank trust), holds the offer. See the approval block below.
const trustLevel = String(item.supplierTrust || '').toLowerCase();
const autoApproved = ['high', 'medium', 'low'].includes(trustLevel);

const toCreate = [];
const toReview = [];
const productsToCreate = [];
const seenNewKeys = new Set();

for (const offer of item.offers || []) {
  const productId = productIndex.get(offer.productKey) || null;

  const fields = {
    'Offer Name': buildOfferName(offer, item),
    'Status': 'Live',
    'Offer Date': today,
    'Auto Expiry Days': validityDays,   // invariant 1

    'Brand': offer.brand || '',
    'Product Name': offer.productName,
    'Variant': offer.variant || '',
    'Volume ML': offer.volumeMl,
    'PCS/Case': offer.pcsCase,
    'Unit Type': offer.unitType,
    'ABV': offer.abv,
    'Origin Country': offer.originCountry || '',
    'Bond/Customs Status': offer.bondStatus,
    'Buy Price': offer.buyPrice,
    'Currency': offer.currency,
    'Price Type': offer.priceType,
    'Stock Cases': offer.stockCases,
    'Weight KG': offer.weightKg,
    'Cases per Pallet': offer.casesPerPallet,
    'Pieces per Pallet': offer.piecesPerPallet,
    'Language': offer.language || '',
    'MOQ': offer.moq || '',
    'Lead Time': offer.leadTime || '',
    'EAN Unit': offer.eanUnit || '',
    'EAN Case': offer.eanCase || '',
    'BBD': offer.bbd,
    'Incoterm': offer.incoterm,
    'Warehouse': offer.warehouse,

    'Source Sheet': offer.sourceSheet,
    'Source Message ID': offer.sourceMessageId || '',
    'Notes': `Ingested from ${offer.sourceSheet} row ${offer.sheetRow} on ${today}.`,
  };

  if (offer.category) fields['Category'] = offer.category;
  if (item.supplierRecordId) fields['Supplier'] = [item.supplierRecordId];

  // Price Level gates dispatch: Send Eligible requires Sharp or Normal, and a
  // BLANK value fails it as hard as High does. Left unset it silently parked
  // 1,232 of 1,728 live offers. Normal is the neutral reading; Sharp and High
  // are the deliberate calls a trader makes afterwards.
  fields['Price Level'] = 'Normal';

  // ── Trust-driven processing approval (Anil, 2026-08-04) ───────────────────
  // Offer Approval Status is a PROCESSING status: Approved for supplier Trust
  // High/Medium/Low, Awaiting Approval only for Trust = Hold or an unresolved
  // supplier. It is NOT a human control point. The human approvals live
  // elsewhere and are NEVER written by ingestion: Listing Approved (website
  // tick, Anil or Annika) and Gate 2 dispatch approval (Anil or Annika). So an
  // auto-approved offer still cannot reach the public site or a client inbox
  // without a person acting.
  fields['Offer Approval Status'] = autoApproved ? 'Approved' : 'Awaiting Approval';
  if (!autoApproved) {
    fields['Notes'] += ` HELD at Awaiting Approval: supplier trust is ${item.supplierTrust || 'unknown/unresolved'} — only Hold or unknown suppliers hold since 2026-08-04.`;
  }

  // A product we have not seen is created rather than parked. Near-duplicate
  // catalogue entries are a tidy-up job; 1,103 live offers with no product link
  // was a stoppage. New records are flagged Needs Review so the duplicates stay
  // findable, and the offer links by Product Key — Airtable resolves a link
  // field written as its primary-field value when the node has typecast on.
  if (productId) {
    fields['Products'] = [productId];
  } else {
    fields['Products'] = [offer.productKey];
    if (!seenNewKeys.has(offer.productKey)) {
      seenNewKeys.add(offer.productKey);
      productsToCreate.push({ fields: stripEmpty({
        'Product Key': offer.productKey,
        'Brand': offer.brand || '',
        'Product Name': offer.productName,
        'Variant': offer.variant || '',
        'Category': offer.category,
        'Volume ML': offer.volumeMl,
        'PCS/Case': offer.pcsCase,
        'Unit Type': offer.unitType,
        'ABV': offer.abv,
        'Origin Country': offer.originCountry || '',
        'Bond/Customs Status': offer.bondStatus,
        'EAN Unit': offer.eanUnit || '',
        'EAN Case': offer.eanCase || '',
        'Status': 'Needs Review',
        'Notes': `Created automatically from ${offer.sourceSheet} on ${today}. `
               + 'Check it is not a duplicate of an existing product spelled differently.',
      }) });
    }
  }

  toCreate.push({ fields: stripEmpty(fields) });
}

const exceptions = (item.exceptions || []).map((e) => ({
  sheetRow: e.sheetRow,
  productName: e.productName,
  reason: e.exceptionReason,
  sourceSheet: e.sourceSheet,
}));

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    supplierRecordId: item.supplierRecordId,
    createCount: toCreate.length,
    reviewCount: toReview.length,
    newProductCount: productsToCreate.length,
    exceptionCount: exceptions.length,
    toCreate,
    toReview,
    productsToCreate,
    exceptions,
    summary:
      `${item.fileName} :: ${item.sheetName} — ` +
      `${toCreate.length} offers, ${productsToCreate.length} new products, ` +
      `${exceptions.length} bad rows`,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Records from a named upstream node. Returns [] rather than throwing when the
 * node is absent, so the same file works in a workflow that does not have it.
 */
function nodeRecords(name) {
  try {
    return $(name).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
}

function buildProductIndex(products) {
  const index = new Map();
  for (const p of products) {
    const f = p.fields || p;
    const key = [
      norm(f['Brand']),
      norm(f['Product Name']),
      f['Volume ML'] ?? '',
      norm(f['Bond/Customs Status']),
    ].join('|');
    if (!index.has(key)) index.set(key, p.id);
  }
  return index;
}

/**
 * Offer Name is the primary field and is explicitly internal — it may carry the
 * supplier name. Public display uses Public Product Description instead.
 */
function buildOfferName(offer, ctx) {
  const parts = [offer.brand, offer.productName, offer.variant].filter(Boolean);
  const spec = offer.volumeMl ? `${offer.volumeMl}ml` : '';
  const supplier = ctx.supplierName ? ` - ${ctx.supplierName}` : '';
  return `${parts.join(' ')}${spec ? ' ' + spec : ''}${supplier} ${new Date().toISOString().slice(0, 10)}`.trim();
}

/** Airtable rejects null on some field types; omit rather than send empties. */
function stripEmpty(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields)) {
    if (READ_ONLY.has(k)) continue;
    if (v === null || v === undefined || v === '') continue;
    out[k] = v;
  }
  return out;
}

/**
 * n8n Code node — "Offers to Create"
 * Mode: Run Once for All Items
 *
 * Sits between "Create Products" and "Create Offers" and emits one item per
 * offer record.
 *
 * It exists because of an ordering constraint, not because there is any work to
 * do here. An offer whose product is new links to it by Product Key, and that
 * link only resolves once the Product row exists — so "Create Products" has to
 * run first. But an Airtable node REPLACES the items flowing through it, so by
 * the time the newly created products come out the other side, the offer
 * payloads are gone. This reaches back to the payload builder by name and puts
 * them back on the wire.
 *
 * "Create Products" is set to always output data, so a batch where every
 * product already existed still reaches this node instead of ending the branch.
 */

// Emitted FLAT, not wrapped in { fields: ... }. The Airtable node's
// "Map Automatically" mode reads the item's top-level keys as column names, so
// a nested wrapper would be written as a single column called "fields".
const offers = [];

for (const item of $('Build Airtable Payload').all()) {
  for (const record of item.json.toCreate || []) {
    offers.push({ json: record.fields || record });
  }
}

return offers;

/**
 * n8n Code node — "Route to Review"
 * Mode: Run Once for Each Item
 *
 * The hand-off point. Every email this pipeline cannot parse ends up here with
 * a plain-English reason, ready for a person to map or key in by hand.
 *
 * At 5-10 offers a day with someone available to handle the remainder, an
 * unparsed email is a hand-off, not a failure. What matters is that the reason
 * is specific enough to act on without reopening the original — "no profile"
 * is useless, "no profile for cse.ltd@cytanet.com.cy" tells you exactly what
 * to create.
 *
 * Nothing here deletes, hides or alters the email.
 */

const item = $input.item.json;

const sender = item.fromAddress || item.envelopeFrom || '(unknown sender)';
const subject = item.subject || '(no subject)';

let category;
let reason;
let action;

if (item.skipReason && /Spreadsheet attached/i.test(item.skipReason)) {
  // Not a failure at all — the Excel workflow owns this one.
  category = 'Handled elsewhere';
  reason = item.skipReason;
  action = 'None. The Excel workflow ingests this email.';

} else if (item.skipIngestion) {
  category = 'Skipped on purpose';
  reason = item.skipReason || 'Supplier is gated out of ingestion';
  action = 'None, unless the commercial position has changed — untick Skip Offer Ingestion, or change the supplier Status.';

} else if (item.blocksFound === 0) {
  category = 'Nothing to parse';
  reason = item.exceptionReason || 'No table or label:value block found in the body';
  action = 'Read it. If it is an offer, it is in a shape the parser does not yet handle — key it in, or send it over so the shape can be added.';

} else if (item.profileFound === false && /references labels absent/i.test(item.exceptionReason || '')) {
  category = 'Profile no longer fits';
  reason = item.exceptionReason;
  action = 'The supplier changed their layout. Update the Column Map on their Sheet Profile.';

} else if (item.profileFound === false) {
  category = 'No profile for this sender';
  reason = item.exceptionReason || `No email profile matches ${sender}`;
  action = `Key this one in, then create a Sheet Profile with Sender Match = ${domainOf(sender) || sender} so the next one parses automatically.`;

} else {
  category = 'Unclassified';
  reason = item.exceptionReason || 'Could not be parsed, reason not recorded';
  action = 'Read it and decide.';
}

return {
  json: {
    ...item,
    reviewCategory: category,
    reviewReason: reason,
    reviewAction: action,
    reviewSender: sender,
    reviewSubject: subject,
    // Single line for the execution log, so a skim of recent runs shows what
    // is being handed off and why without opening each one.
    reviewSummary: `[${category}] ${subject} — from ${sender}. ${reason}`,
    // Carried explicitly: the label step needs it, and on the no-blocks path
    // the earlier nodes may not have populated the usual fields.
    threadId: item.threadId || null,
  },
};

function domainOf(address) {
  const m = String(address).match(/@([^\s>]+)$/);
  return m ? m[1].toLowerCase() : null;
}

// n8n Code node — "Flatten Block" (Run Once for Each Item)
// Turns the first extracted block into the headerCells + dataRows shape the
// SHARED Normalize Rows / Resolve Body Profile code expects, and stamps the
// source identifiers the email path never set.
const item = $input.item.json;
const blocks = Array.isArray(item.blocks) ? item.blocks : [];
const first = blocks[0] || null; // first/primary block only, by design

let headerCells = [];
let dataRows = [];
if (first && Array.isArray(first.rows) && first.rows.length) {
  headerCells = first.rows[0] || [];
  dataRows = first.rows.slice(1);
}

const subject = item.subject || '(no subject)';
return {
  json: {
    ...item,
    headerCells,
    dataRows,
    fileName: `Email: ${subject}`,
    sheetName: first && first.type === 'labels' ? 'Body (labels)' : 'Body',
    sourceMessageId: item.id || item.messageId || item.sourceMessageId || null,
    blockType: first ? first.type : null,
  },
};

// n8n Code node — "Attach Profiles" (Run Once for All Items)
// The Airtable lookup above REPLACES the items on the wire, so the email items
// are read back by name and the full profile candidate list is joined onto
// every one — keeping one item per email.
const profiles = $('Find Email Profiles').all()
  .map((i) => i.json)
  .filter((p) => p && (p.id || Object.keys(p).length > 0));

return $('Flatten Block').all().map((entry) => ({
  json: { ...entry.json, profileCandidates: profiles },
}));

// n8n Code node — "Restore Offers" (Run Once for All Items)
// The Products lookup above REPLACES the items on the wire. Re-emit the
// per-email offer batches so Build Airtable Payload sees item.offers again.
// Two possible upstream sources now exist depending on which branch the email
// took: the profile-matched path (Normalize Rows) or the new-supplier LLM
// path (Attach New Supplier & Finalize Offers). Only one of the two will
// actually have execution data for any given run, so each is read defensively.
let fromProfile = [];
try { fromProfile = $('Normalize Rows').all().map((entry) => ({ json: entry.json })); } catch (e) { /* did not run this branch */ }

let fromNewSupplier = [];
try { fromNewSupplier = $('Attach New Supplier & Finalize Offers').all().map((entry) => ({ json: entry.json })); } catch (e) { /* did not run this branch */ }

return [...fromProfile, ...fromNewSupplier];

// "Emails to Mark Done" -- emits ONE item per distinct source email, carrying
// the Gmail message ID that "Mark Email Done" needs to apply the done-label.
// Two possible upstream sources of one-item-per-email data now exist: the
// profile-matched path (Normalize Rows) or the new-supplier LLM path (Attach
// New Supplier & Finalize Offers). Every Airtable node between here and
// either of those REPLACES the items on the wire, so both are read
// defensively and only whichever one actually ran contributes.
let fromProfile = [];
try { fromProfile = $('Normalize Rows').all(); } catch (e) { /* did not run this branch */ }

let fromNewSupplier = [];
try { fromNewSupplier = $('Attach New Supplier & Finalize Offers').all(); } catch (e) { /* did not run this branch */ }

const seen = new Set();
const out = [];

for (const entry of [...fromProfile, ...fromNewSupplier]) {
  const id = entry.json.sourceMessageId;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { messageId: String(id), offerCount: entry.json.parsedCount ?? null } });
}

return out;

let original;
try {
  original = $('Carry Existing Supplier Id Forward').all()[$itemIndex].json;
} catch (e) {
  original = $('New Sender or Skip?').all()[$itemIndex].json;
}
const extracted = $('LLM Extract Offers').item.json;

let supplierId = null;
let supplierName = null;
try {
  const created = $('Create New Supplier').item.json;
  supplierId = created.id;
  supplierName = created.fields ? created.fields['Supplier Name'] : created['Supplier Name'];
} catch (e) {
  supplierId = original.existingSupplierId || null;
  supplierName = original.senderDomain || original.fromAddress || null;
}

function key(o) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(o.brand), n(o.productName), o.volumeMl ?? '', n(o.bondStatus)].join('|');
}

const rawOffers = (extracted.output && extracted.output.offers) || extracted.offers || [];
const offers = rawOffers
  .filter((o) => o.productName && o.buyPrice != null && o.currency)
  .map((o, idx) => ({
    ...o,
    productKey: key(o),
    sourceSheet: 'Email (LLM extraction, new sender)',
    sourceMessageId: original.messageId || '',
    sheetRow: idx + 1,
  }));

return {
  json: {
    ...original,
    offers,
    supplierRecordId: supplierId,
    supplierName,
    supplierTrust: 'Medium',
    supplierValidityDays: 14,
  },
};

// A Sheet Profile exists for this sender WITH a real Column Map, but the
// email still reached the no-profile branch -- a data inconsistency worth a
// human look, not something safe to auto-fix.
const original = $json;
const existing = original.profileSearchResult;
return {
  json: {
    ...original,
    exceptionReason: `A working Sheet Profile ("${existing && existing.fields ? existing.fields['Profile Name'] : ''}") already exists for ${original.fromAddress}, but this email did not match it -- check Sender Match spelling/case and the Column Map's header labels rather than creating a duplicate.`,
  },
};

// A Supplier with this email may already exist even though no Email-type
// Sheet Profile matched -- e.g. a supplier we already trade with via
// Spreadsheet-type profiles, now also emailing offers directly in the
// message body for the first time. Not a duplicate case: just needs a new
// Email-type profile alongside their existing one.
// IMPORTANT: $input.item.json here is the SUPPLIER search result (or a
// synthetic {} via alwaysOutputData), not the original email -- spreading it
// directly would overwrite fromAddress/subject/blocks/prose with Supplier
// fields. Read the original email fields from the incoming item's own
// carried-forward state instead (merged in upstream by 'Merge Original
// Fields Back'), which flowed through 'Has Working Column Map?' unchanged.
const supplierSearchResult = $input.item.json;
const original = $('Merge Original Fields Back').all()[$itemIndex].json;
const existingSupplierId = supplierSearchResult && supplierSearchResult.id ? supplierSearchResult.id : null;
return {
  json: {
    ...original,
    existingSupplierId,
    existingProfileId: null,
  },
};

// 'Search Existing Sheet Profile by Sender' replaces the item with the
// Airtable search result (or a synthetic {} via alwaysOutputData). Re-attach
// the original email fields by INDEX rather than paired-item lookup --
// alwaysOutputData's synthetic items break n8n's normal item-pairing
// resolution ('Multiple matches found'), so $('Node').item is unsafe here.
// From this point on, everything downstream reads fields directly off $json
// instead of reaching back to named nodes, which sidesteps the ambiguity
// entirely for the rest of the chain.
const searchResult = $input.item.json;
const original = $('New Sender or Skip?').all()[$itemIndex].json;
return {
  json: {
    ...original,
    profileSearchResult: searchResult,
  },
};

/**
 * n8n Code node — "Extract Body Blocks"
 * Mode: Run Once for Each Item
 *
 * Pulls offer content out of an EMAIL BODY, as opposed to an attachment.
 *
 * Emits blocks of two shapes, because supplier emails come in both:
 *
 *   table   — a grid, from an HTML <table> or from delimited plain text.
 *             Bluebird, Brockagh, Rio Mare, Fairy, the drinks list.
 *   labels  — vertical "Label: value" pairs describing ONE product.
 *             Marco Polo writes offers this way; there is no table at all.
 *
 * It also returns the surrounding PROSE, which is not decoration. These emails
 * routinely state offer-wide terms in sentences around the grid rather than in
 * columns — "Terms: T2 | EXW Loendersloot", "Lead Time: Approximately 2 weeks",
 * "MOQ 1 pallet/line", "This is ex-works Virginia". A parser that reads only
 * the table silently drops the incoterm, the warehouse and the lead time.
 *
 * Signature blocks are removed first. Brockagh's footer carries a street
 * address and two phone numbers, which is exactly the kind of thing a
 * delimited-text reader will happily treat as a data row.
 */

const item = $input.item.json;

// ── The attachment always wins ──────────────────────────────────────────────
// An email may carry BOTH a spreadsheet and a summary table in the body. The
// spreadsheet is authoritative — it is the full list, while the body is
// usually an excerpt — so the body is not parsed when one is present. Without
// this, the Excel workflow and this one both ingest the same offer.
const SPREADSHEET = /\.(xlsx|xlsm|xltx|xls|csv|tsv)$/i;
const attached = Object.values($input.item.binary || {})
  .map((b) => String(b.fileName || ''))
  .filter((n) => SPREADSHEET.test(n));

if (attached.length) {
  return { json: { ...item, blocksFound: 0, blocks: [], prose: '',
    skipReason: `Spreadsheet attached (${attached.join(', ')}) — the Excel workflow handles this email` } };
}

const html = String(item.bodyHtml || item.html || '');
const plain = String(item.bodyPlain || item.text || item.body || item.snippet || '');

const source = html || plain;
if (!source.trim()) {
  return { json: { ...item, blocksFound: 0, blocks: [], prose: '',
    exceptionReason: 'Email body is empty' } };
}

// ── 1. Trim quoted history and the signature ────────────────────────────────
const asText = html ? htmlToText(html) : plain;
const trimmed = stripSignature(stripQuoted(asText));

// ── 1b. Who actually sent the offer ─────────────────────────────────────────
// Offers arrive FORWARDED into offers@akay.ie, so the envelope sender is
// always the forwarder, not the supplier. Keying profiles on it would match
// one address for every supplier in the business. The real sender sits in the
// forwarded header block.
const forwarded = forwardedSender(asText);
const envelope = extractEmail(item.from || item.fromAddress || '');
const effective = forwarded || envelope;

// ── 2. Tables ───────────────────────────────────────────────────────────────
const blocks = [];

if (html) {
  // Scan only the forwarded portion. Everything before the marker is the
  // forwarder's own message, and an email signature is itself built from
  // <table> for layout — left in, it is extracted as a two-column price list.
  for (const grid of htmlTables(afterForward(html))) {
    if (grid.length >= 2) blocks.push({ type: 'table', rows: grid });
  }
}

// Plain-text grids. Only attempted when HTML yielded nothing, so a well-formed
// HTML table is never also parsed a second time from its text rendering.
if (blocks.length === 0) {
  for (const grid of textTables(trimmed)) {
    if (grid.length >= 2) blocks.push({ type: 'table', rows: grid });
  }
}

// ── 3. Label:value blocks ───────────────────────────────────────────────────
// Only when no table was found. An email with a grid may still contain
// "Lead Time: 2 weeks" lines, and those are offer-wide prose, not a product.
if (blocks.length === 0) {
  const labels = labelValueBlock(trimmed);
  if (labels) blocks.push({ type: 'labels', ...labels });
}

return {
  json: {
    ...item,
    blocksFound: blocks.length,
    blocks,
    // Handed to the profile so offer-wide terms can be lifted from sentences.
    //
    // Grid lines are removed first. Left in, the table's own column headings
    // are read as prose: a "MOQ" heading matches the MOQ rule and captures the
    // rest of the header row ("HS Code / Inner / Outer") as the offer-wide
    // minimum order. Harmless when MOQ is also mapped per row, since the row
    // value wins — silently wrong when it is not.
    prose: proseOnly(trimmed).slice(0, 8000),
    fromAddress: effective,
    senderDomain: (effective.split('@')[1] || ''),
    envelopeFrom: envelope,
    forwardedFrom: forwarded,
    // True when the supplier was recovered from a forwarded header rather than
    // the envelope. Useful when a profile fails to match and someone is
    // working out why.
    senderFromForward: Boolean(forwarded),
    exceptionReason: blocks.length ? null
      : 'No table or label:value block found in the email body',
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/** HTML from the forwarded marker onward, or all of it when not a forward. */
function afterForward(src) {
  const m = src.match(/-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}/i)
         || src.match(/Begin forwarded message:/i);
  return m && m.index !== undefined ? src.slice(m.index) : src;
}

/**
 * A layout table used for a signature, not a price list. Signatures carry
 * contact links and images; offer tables carry neither.
 */
function isSignatureTable(t) {
  return /<img\b/i.test(t) || /href\s*=\s*["']?(?:tel:|mailto:)/i.test(t);
}

/** Rows of cells from every <table> in the HTML. */
function htmlTables(src) {
  const out = [];
  const tables = src.match(/<table[\s\S]*?<\/table>/gi) || [];

  for (const t of tables) {
    if (isSignatureTable(t)) continue;
    const rows = [];
    for (const tr of t.match(/<tr[\s\S]*?<\/tr>/gi) || []) {
      const cells = (tr.match(/<t[dh][\s\S]*?<\/t[dh]>/gi) || []).map(cellText);
      if (cells.some((c) => c !== '')) rows.push(cells);
    }
    if (rows.length) out.push(rows);
  }
  return out;
}

function cellText(cell) {
  return decode(cell.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

/**
 * Grids in plain text. A run of consecutive lines sharing the same delimiter
 * and a consistent column count is treated as one table.
 *
 * Tabs are tried before multi-space, because a tab-delimited line also contains
 * runs of spaces inside product names ("Absolut Blue Original") and splitting
 * on those would shred the row.
 */
function textTables(text) {
  const lines = text.split('\n').map((l) => l.replace(/\s+$/, ''));
  const out = [];
  let current = null;

  for (const line of lines) {
    const cells = splitRow(line);

    if (cells && cells.length >= 2) {
      if (current && current[0].length === cells.length) current.push(cells);
      else { if (current && current.length >= 2) out.push(current); current = [cells]; }
    } else {
      if (current && current.length >= 2) out.push(current);
      current = null;
    }
  }
  if (current && current.length >= 2) out.push(current);
  return out;
}

/**
 * Drop lines that are grid rows, keeping only the sentences around the table.
 * A line that splits into two or more cells is part of the table, not prose.
 */
function proseOnly(text) {
  return text
    .split('\n')
    .filter((line) => {
      const cells = splitRow(line);
      return !(cells && cells.length >= 2);
    })
    .join('\n');
}

function splitRow(line) {
  if (!line.trim()) return null;
  if (line.includes('\t')) return line.split('\t').map((c) => c.trim());

  // Two or more spaces as a column break — how pasted grids usually survive.
  const parts = line.split(/ {2,}/).map((c) => c.trim()).filter(Boolean);
  return parts.length >= 2 ? parts : null;
}

/**
 * "Label: value" lines describing a single product.
 *
 * Returns the labels as a header row and the values as one data row, so the
 * SAME downstream mapping applies — a profile maps a field to a column index
 * either way, and nothing after this node needs to know which shape it was.
 */
function labelValueBlock(text) {
  const labels = [];
  const values = [];
  let title = '';

  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line) continue;

    const m = line.match(/^([A-Za-z][A-Za-z0-9 \/&().'-]{1,40}?)\s*:\s*(.+)$/);
    if (!m) {
      // A line ending in a colon with nothing after it is a heading. Keep the
      // LAST one seen before the pairs begin, not the first: these emails open
      // with a prose lead-in that also ends in a colon ("Please see the
      // following offers for ...:"), and the product heading sits below it,
      // directly above the values it describes.
      if (labels.length === 0 && /:$/.test(line) && line.length > 8) {
        title = line.replace(/:$/, '').trim();
      }
      continue;
    }

    const label = m[1].trim();
    const value = m[2].trim();

    // Contact-detail labels are not product attributes.
    if (/^(tel|fax|mobile|office|email|e-?mail|phone|web|www|http)/i.test(label)) continue;

    labels.push(label);
    values.push(value);
  }

  if (labels.length < 2) return null;

  if (title) { labels.unshift('Product'); values.unshift(title); }
  return { rows: [labels, values], title };
}

/**
 * Separate the message we care about from the surrounding conversation.
 *
 * A FORWARD and a REPLY need opposite treatment, and getting it backwards
 * deletes the offer:
 *
 *   forward — the offer is what follows the marker. Everything BEFORE it is
 *             the forwarder's own signature and covering note, so drop that.
 *   reply   — the offer, if any, is what precedes the marker. Everything
 *             after is the earlier message, so drop that.
 *
 * The previous version treated a bare "From:" line as a reply marker, which
 * cut at the forwarded header and removed the entire forwarded offer.
 */
function stripQuoted(text) {
  const fwd = text.match(/^-{2,}\s*Forwarded message\s*-{2,}\s*$/im)
           || text.match(/^-{2,}\s*Original Message\s*-{2,}\s*$/im)
           || text.match(/^\s*Begin forwarded message:\s*$/im);

  let body = text;
  if (fwd && fwd.index !== undefined) {
    // Skip past the forwarded header block (From/Date/Subject/To lines).
    const after = body.slice(fwd.index + fwd[0].length);
    const headerEnd = after.search(/\n\s*\n/);
    body = headerEnd >= 0 ? after.slice(headerEnd) : after;
  }

  const reply = body.match(/^\s*On .+ wrote:\s*$/m) || body.match(/^_{5,}\s*$/m);
  return reply && reply.index !== undefined ? body.slice(0, reply.index) : body;
}

/**
 * The supplier's address from a forwarded header block. Taken only from the
 * lines directly under the forward marker, so a mailto: elsewhere in the body
 * cannot be mistaken for the sender.
 */
function forwardedSender(text) {
  const fwd = text.match(/^-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}\s*$/im)
           || text.match(/^\s*Begin forwarded message:\s*$/im);
  if (!fwd || fwd.index === undefined) return null;

  const header = text.slice(fwd.index, fwd.index + 600);
  const m = header.match(/^\s*From:\s*.*?([^\s<>"]+@[^\s<>"]+\.[a-z]{2,})/im);
  if (!m) return null;

  const addr = m[1].toLowerCase().replace(/[.,;>]+$/, '');
  // A forward of our own mail is not a supplier.
  return /@akay\.ie$/i.test(addr) ? null : addr;
}

/**
 * Drop the sign-off and everything after it. Supplier footers carry street
 * addresses and phone numbers that a delimited-text reader treats as rows.
 */
function stripSignature(text) {
  const re = /^\s*(kind regards|best regards|regards|many thanks|thanks and regards|br|yours (sincerely|faithfully))\s*[,.]?\s*$/im;
  const m = text.match(re);
  return m && m.index !== undefined ? text.slice(0, m.index) : text;
}

function htmlToText(src) {
  return decode(
    src
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
      .replace(/<\/(p|div|tr|h[1-6]|li)>/gi, '\n')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/t[dh]>/gi, '\t')
      .replace(/<[^>]+>/g, '')
  ).replace(/[ \t]+\n/g, '\n');
}

function decode(s) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', euro: '€', pound: '£' };
  return String(s)
    .replace(/&#(\d+);/g, (_m, d) => String.fromCharCode(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_m, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => named[n.toLowerCase()] ?? m);
}

function extractEmail(raw) {
  const m = String(raw).match(/<([^>]+)>/);
  return (m ? m[1] : String(raw)).trim().toLowerCase();
}

/**
 * n8n Code node — "Resolve Body Profile"
 * Mode: Run Once for Each Item
 *
 * Picks the Sheet Profile for an email offer, and lifts offer-wide terms out
 * of the surrounding prose.
 *
 * KEYED ON SENDER, NOT ON A HEADER FINGERPRINT.
 * Spreadsheet profiles fingerprint the header row, which works because the file
 * is machine-generated and the header is stable. Email tables are typed by hand
 * into Outlook: of six real supplier emails, one had no product-name header,
 * one had a blank price header, one was three stacked tables and one had no
 * table at all. There is nothing dependable to fingerprint. The supplier is the
 * stable thing, so that is the key.
 *
 * This also sidesteps the price-column gate. A sender-keyed profile states that
 * the price is column 3 because it is Brockagh — no header word required.
 *
 * TERMS IN PROSE.
 * These emails put per-offer terms in sentences rather than columns:
 *   "Terms: T2 | EXW Loendersloot"
 *   "This is ex-works Virginia."
 *   "Prices EXW in EUR - Zielona Góra, Poland"
 *   "Lead Time: Approximately 2 weeks"
 * Reading only the grid silently drops the incoterm, warehouse and lead time,
 * so the prose is parsed and merged UNDER the profile's own defaults — an
 * explicit profile setting always wins over something inferred from a sentence.
 */

const WAREHOUSES = ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
                    'Greece', 'Indonesia', 'Czech', 'NewCorp', 'Vergèze', 'Bergamo'];
const INCOTERMS = ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP'];

const item = $input.item.json;

// Airtable search results for Sheet Profiles where Profile Type is an email type.
const candidates = (item.profileCandidates || []).map((p) => p.fields || p);

const from = String(item.fromAddress || '').toLowerCase();
const domain = String(item.senderDomain || '').toLowerCase();

// Exact address beats domain: a supplier may have one contact who sends a
// different layout from the rest of the office.
let chosen = candidates.find((p) => match(p['Sender Match']) === from)
          || candidates.find((p) => match(p['Sender Match']) === domain);

const prose = parseProse(String(item.prose || ''));

if (!chosen) {
  return {
    json: {
      ...item,
      profileFound: false,
      proseTerms: prose.terms,
      proseNotes: prose.notes,
      exceptionReason:
        `No email profile for ${from || '(unknown sender)'}` +
        `${domain ? ` or domain ${domain}` : ''} — routed for manual mapping`,
    },
  };
}

// ── Ingestion gate ──────────────────────────────────────────────────────────
// Two separate reasons to skip, deliberately kept apart:
//   Supplier Status Blacklisted/Inactive/Archived — we do not trade with them
//   Skip Offer Ingestion ticked — we do trade, but their prices are routinely
//                                 too high for parsing to be worth it
//
// Neither deletes or hides anything. The email is left exactly as it is and
// simply not ingested, so a person can still read it, and unticking the box
// makes the next offer parse normally.
const supplierStatus = firstName(chosen['Supplier Status']);
const supplierSkip = firstBool(chosen['Supplier Skip']);
const BLOCKING = ['Blacklisted', 'Inactive', 'Archived'];

if (supplierSkip || BLOCKING.includes(supplierStatus)) {
  return {
    json: {
      ...item,
      profileFound: true,
      skipIngestion: true,
      profileName: chosen['Profile Name'],
      skipReason: supplierSkip
        ? `${chosen['Profile Name']}: Skip Offer Ingestion is ticked on the supplier — offers not parsed on price grounds`
        : `${chosen['Profile Name']}: supplier Status is ${supplierStatus} — offers not parsed`,
    },
  };
}

let columnMap = {};
let profileDefaults = {};
try { columnMap = JSON.parse(chosen['Column Map'] || '{}'); } catch (e) { /* reported below */ }
try { profileDefaults = JSON.parse(chosen['Defaults'] || '{}'); } catch (e) { /* reported below */ }

// A Column Map may address columns by INDEX or by LABEL NAME. Label names are
// the right choice for Label:value profiles — the position of "Price" depends
// on which other labels the supplier happened to include that day, so a single
// added line would shift every index. Names are resolved against the extracted
// header here, so everything downstream still sees plain indices.
const headerCells = (item.headerCells || []).map((h) => String(h ?? '').trim().toLowerCase());
if (headerCells.length) {
  const resolved = {};
  const unresolved = [];
  for (const [field, ref] of Object.entries(columnMap)) {
    if (Number.isInteger(ref)) { resolved[field] = ref; continue; }
    const idx = headerCells.indexOf(String(ref).trim().toLowerCase());
    if (idx >= 0) resolved[field] = idx;
    else unresolved.push(`${field} -> "${ref}"`);
  }
  columnMap = resolved;
  if (unresolved.length) {
    return { json: { ...item, profileFound: false, proseTerms: prose.terms,
      exceptionReason:
        `Profile "${chosen['Profile Name']}" references labels absent from this email: ` +
        `${unresolved.join(', ')}. Labels present: ${headerCells.filter(Boolean).join(', ')}` } };
  }
}

if (!Object.keys(columnMap).length) {
  return { json: { ...item, profileFound: false,
    exceptionReason: `Profile "${chosen['Profile Name']}" has an unreadable Column Map` } };
}

return {
  json: {
    ...item,
    profileFound: true,
    profileName: chosen['Profile Name'],
    profileType: name(chosen['Profile Type']),

    // The profile's linked Supplier, forwarded so 04 can link the offer and
    // read the trust level. Without this the email path created every offer
    // with no Supplier at all — the fields all looked right and nothing said
    // who to buy from.
    supplierRecordId: linkId(chosen['Supplier']),
    supplierName: linkName(chosen['Supplier']),
    // High auto-approves the PUBLIC LISTING only. The send to clients still
    // waits for a person, on every supplier.
    supplierTrust: firstName(chosen['Supplier Trust']),

    columnMap,
    // Prose terms fill gaps the profile leaves; they never override it.
    profileDefaults: { ...prose.terms, ...profileDefaults },
    proseTerms: prose.terms,
    proseNotes: prose.notes,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

function match(v) { return String(v ?? '').trim().toLowerCase(); }
function name(v) { return v && typeof v === 'object' ? v.name : v; }

/** Airtable lookups always return arrays, even for a single linked record. */
function firstName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return a && typeof a === 'object' ? a.name : (a ?? null);
}
function firstBool(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return Boolean(a);
}

/**
 * A linked-record field, which Airtable returns as bare record-ID strings over
 * the REST API but as { id, name } objects through some clients. Both shapes
 * are handled so the supplier link survives either.
 */
function linkId(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (!a) return null;
  return typeof a === 'object' ? (a.id || null) : String(a);
}
function linkName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  return a && typeof a === 'object' ? (a.name || null) : null;
}

/**
 * Pull offer-wide terms out of the prose around the table.
 *
 * Deliberately conservative: a term is only taken when its wording is
 * unambiguous. Anything recognised but unmappable is reported in `notes` for a
 * human rather than guessed into a field.
 */
function parseProse(text) {
  const terms = {};
  const notes = [];
  const t = text.replace(/\s+/g, ' ');

  // Incoterm — "EXW Loendersloot", "ex-works Virginia", "DAP Holland"
  const inco = t.match(/\b(ex[\s-]?works?|exw|fca|fob|cfr|cif|dap|ddp)\b/i);
  if (inco) {
    const raw = inco[1].toLowerCase().replace(/[\s-]/g, '');
    terms.incoterm = /^ex(works?)?$/.test(raw) ? 'EXW' : inco[1].toUpperCase();
  }

  // Warehouse — matched against the Airtable option list only.
  for (const w of WAREHOUSES) {
    if (new RegExp(`\\b${escapeRe(w)}\\b`, 'i').test(t)) { terms.warehouse = w; break; }
  }

  // A location was clearly stated but is not one of our warehouses. Reported
  // rather than forced to "Other", because the name matters to a human:
  // "ex-works Virginia" is Virginia in Co. Cavan, not the US state, and
  // guessing wrong puts the goods on another continent.
  if (!terms.warehouse && inco) {
    const after = t.slice(inco.index + inco[0].length).match(/^\s*[:\-]?\s*([A-ZÀ-Ý][\w'’-]*(?:\s+[A-ZÀ-Ý][\w'’-]*){0,3})/);
    if (after) notes.push(`Stated location "${after[1].trim()}" is not a known warehouse — set it by hand`);
  }

  // Bond / customs status
  if (/\bT1\b/.test(t)) terms.bondStatus = 'T1';
  else if (/\bT2\b/.test(t)) terms.bondStatus = 'T2';
  else if (/\bduty[\s-]?paid\b/i.test(t)) terms.bondStatus = 'Duty Paid';
  else if (/\b(under )?bond(ed)?\b/i.test(t)) terms.bondStatus = 'Bonded';

  // Currency stated in prose — "Prices EXW in EUR"
  const cur = t.match(/\bprices?\b[^.]{0,40}?\b(eur|euro|usd|gbp|aed|sgd)\b/i);
  if (cur) terms.currency = cur[1].toUpperCase().replace('EURO', 'EUR');

  // Lead time and MOQ are matched PER LINE, and stopped at the next known
  // keyword. Flattened whole-text matching runs straight past the end of the
  // value: one real email reads "Lead time 2 weeks / MOQ 1 pallet per line /
  // Price is EXW Athens" on consecutive lines, and a greedy match captured all
  // three as the lead time.
  const STOP = /\b(moq|lead\s*time|price|prices|terms|warehouse|incoterm|delivery|payment)\b/i;

  for (const line of text.split('\n').map((l) => l.trim()).filter(Boolean)) {
    if (!terms.leadTime) {
      const lead = line.match(/lead[\s-]?time\s*[:\-]?\s*(?:approx(?:imately)?\.?\s*)?(.+)$/i);
      if (lead) terms.leadTime = clip(lead[1], STOP);
    }
    if (!terms.moq) {
      const moq = line.match(/\bmoq\b\s*[:\-]?\s*(.+)$/i);
      if (moq) terms.moq = clip(moq[1], STOP);
    }
  }

  return { terms, notes };
}

/** Trim a captured value at the next keyword, sentence end or pipe. */
function clip(value, stop) {
  let v = String(value).split(/[.|]/)[0].trim();
  const m = v.match(stop);
  if (m && m.index > 0) v = v.slice(0, m.index).trim();
  return v.replace(/[,;\/\s]+$/, '').slice(0, 60);
}

function escapeRe(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/**
 * n8n Code node — "Normalize Rows"
 * Mode: Run Once for Each Item
 *
 * Applies a Sheet Profile's column map to the raw data rows and coerces every
 * value into something the Airtable Offers table will actually accept.
 *
 * This node writes NO approval fields. Ingested offers land as
 * "Awaiting Approval" and are gated by the existing human sign-off.
 */

// ── Airtable single-select options (base appaDSdZkAE9PGkjT, table Offers) ────
// Airtable rejects writes containing an unknown option, so every free-text
// value is coerced into one of these or dropped to a flagged exception.
const OPTIONS = {
  currency: ['EUR', 'USD', 'GBP', 'AED', 'SGD', 'Other'],
  unitType: ['Bottle', 'Can', 'Jar', 'Pack', 'Piece', 'Other'],
  priceType: ['Per Case', 'Per Bottle', 'Per Can', 'Per Piece', 'Per Pack', 'Per Jar'],
  bond: ['Bonded', 'T1', 'T2', 'Duty Paid', 'On Floor', 'Other'],
  incoterm: ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP', 'Other'],
  warehouse: ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
              'Greece', 'Indonesia', 'Czech', 'Other', 'NewCorp', 'Vergèze', 'Bergamo'],
  // Offers.Category has no "Wine" option — it was renamed to "Champagne" on
  // 2026-07-29, since still wine is not a category Akay trades in volume.
  // Everything vinous therefore lands in Champagne, sparkling or not.
  // NOTE: Products.Category still carries BOTH Wine and Champagne. That does
  // not affect product matching, whose key is Brand + Name + Volume +
  // Bond/Customs Status and does not include category.
  category: ['Beer', 'Spirits', 'Champagne', 'Grocery', 'Confectionery',
             'Toiletries', 'Soft Drinks', 'Other FMCG'],
};

// Declared here rather than beside parseVolume: the row loop runs before the
// helper block, and `const` does not hoist the way a function declaration does.
const VOLUME_UNIT_FACTOR = { ml: 1, cc: 1, cl: 10, dl: 100, l: 1000, ltr: 1000, litre: 1000 };

// Same reason as above. parseDate calls this from inside the row loop, which
// runs before the helper block below is evaluated. Latent until a profile
// mapped a BBD column — none of the first five did, so it never fired.
const pad = (v) => String(v).padStart(2, '0');

const SYNONYMS = {
  currency: {
    '€': 'EUR', eur: 'EUR', euro: 'EUR', euros: 'EUR',
    $: 'USD', usd: 'USD', dollar: 'USD', usdollar: 'USD',
    '£': 'GBP', gbp: 'GBP', pound: 'GBP', sterling: 'GBP',
    aed: 'AED', dirham: 'AED', sgd: 'SGD',
  },
  bond: {
    bond: 'Bonded', bonded: 'Bonded', underbond: 'Bonded', inbond: 'Bonded',
    t1: 'T1', t2: 'T2', export: 'T1', eu: 'T2', community: 'T2',
    dutypaid: 'Duty Paid', dp: 'Duty Paid', taxpaid: 'Duty Paid',
    onfloor: 'On Floor', floor: 'On Floor', exstock: 'On Floor',
  },
  unitType: {
    bottle: 'Bottle', btl: 'Bottle', flasche: 'Bottle', bouteille: 'Bottle',
    can: 'Can', cans: 'Can', tin: 'Can',
    jar: 'Jar', pack: 'Pack', pouch: 'Pack', piece: 'Piece', pcs: 'Piece', unit: 'Piece',
  },
  category: {
    beer: 'Beer', lager: 'Beer', ale: 'Beer', cider: 'Beer',
    spirit: 'Spirits', spirits: 'Spirits', whisky: 'Spirits', whiskey: 'Spirits',
    vodka: 'Spirits', gin: 'Spirits', rum: 'Spirits', liqueur: 'Spirits',
    cognac: 'Spirits', brandy: 'Spirits', tequila: 'Spirits',
    champagne: 'Champagne', wine: 'Champagne', wines: 'Champagne',
    prosecco: 'Champagne', sparkling: 'Champagne', cava: 'Champagne', bordeaux: 'Champagne',
    softdrink: 'Soft Drinks', softdrinks: 'Soft Drinks', water: 'Soft Drinks',
    juice: 'Soft Drinks', energy: 'Soft Drinks', soda: 'Soft Drinks',
    grocery: 'Grocery', food: 'Grocery',
    confectionery: 'Confectionery', chocolate: 'Confectionery', sweets: 'Confectionery',
    candy: 'Confectionery', biscuit: 'Confectionery',
    toiletries: 'Toiletries', cosmetics: 'Toiletries', personalcare: 'Toiletries',
  },
};

const item = $input.item.json;
const map = item.columnMap || {};       // { targetField: headerCellIndex }
const defaults = item.profileDefaults || {}; // supplier-level fallbacks
const headers = item.headerCells || [];

const offers = [];

// Seeded with anything the extractor already rejected before reaching here.
// The WhatsApp path refuses some lines outright — a price range, an average —
// and those reasons are far more useful than the "unparseable price" this node
// would produce from the same text. Empty on the spreadsheet and email paths.
const exceptions = (item.preParseExceptions || []).map((e) => ({
  sheetRow: e.sheetRow ?? null,
  productName: e.productName || '',
  sourceSheet: `${item.fileName} :: ${item.sheetName}`,
  exceptionReason: e.exceptionReason,
}));

(item.dataRows || []).forEach((row, i) => {
  const sheetRow = (item.headerRowIndex ?? 0) + 2 + i; // 1-based, as seen in Excel
  const get = (field) => {
    const idx = map[field];
    if (idx === undefined || idx === null) return '';
    return String(row[idx] ?? '').trim();
  };

  const productName = get('productName');
  const rawPrice = get('buyPrice');

  // A row without a product name or a price is a spacer, subtotal or footer.
  // Skipping silently is correct here — these are not failures.
  if (!productName && !rawPrice) return;

  const problems = [];

  // Email price cells carry their own currency and per-unit basis; spreadsheet
  // cells are bare numbers and fall back to the profile for both.
  const price = parsePriceCell(rawPrice);
  if (!productName) problems.push('missing product name');
  if (price.value === null) problems.push(`unparseable price "${rawPrice}"`);
  else if (price.ambiguous) problems.push(`ambiguous decimal separator in "${rawPrice}"`);

  // Pack notation lives in its own column on some sheets and inside the
  // product name on others ("Poliakov 6/70cl", "Absolut 120x5cl").
  const pack = parsePack(get('packFormat') || get('volumeMl') || productName);

  const volume = parseVolume(get('volumeMl'), defaults.volumeUnit)
    ?? pack.volumeMl
    ?? parseVolume(productName, defaults.volumeUnit);
  const pcsCase = parseNumber(get('pcsCase')).value ?? pack.pcsCase;
  const abv = parseAbv(get('abv')) ?? pack.abv ?? parseAbv(productName);
  const weightKg = pack.weightG !== null ? pack.weightG / 1000 : null;

  const bond = coerce('bond', get('bondStatus') || defaults.bondStatus);
  const currency = price.currency || coerce('currency', get('currency') || defaults.currency);
  if (!currency) problems.push('no currency on row or profile default');

  const brand = get('brand') || guessBrand(productName);

  const record = {
    sheetRow,
    sourceSheet: `${item.fileName} :: ${item.sheetName}`,
    sourceMessageId: item.sourceMessageId,

    brand,
    productName,
    variant: get('variant') || '',
    category: coerce('category', get('category') || defaults.category),
    volumeMl: volume,
    pcsCase: pcsCase ?? defaults.pcsCase ?? null,
    unitType: coerce('unitType', get('unitType') || defaults.unitType) || 'Bottle',
    abv,
    originCountry: get('originCountry') || defaults.originCountry || '',
    bondStatus: bond,
    buyPrice: price.value,
    currency,
    // A basis stated in the price cell always wins — it is per row, whereas
    // the profile default is per supplier.
    priceType: price.basis
      || coerce('priceType', get('priceType') || defaults.priceType)
      || 'Per Case',
    priceBasisStated: Boolean(price.basis),
    weightKg,
    stockCases: toCases(parseNumber(get('stockCases')).value, pcsCase, defaults.stockUnit),
    casesPerPallet: parseNumber(get('casesPerPallet')).value,
    piecesPerPallet: parseNumber(get('piecesPerPallet')).value,
    language: get('language') || '',
    moq: get('moq') || '',
    leadTime: get('leadTime') || '',
    eanUnit: cleanEan(get('eanUnit')),
    eanCase: cleanEan(get('eanCase')),
    bbd: parseDate(get('bbd')),
    incoterm: coerce('incoterm', get('incoterm') || defaults.incoterm),
    warehouse: coerce('warehouse', get('warehouse') || defaults.warehouse),

    // Identity key per the Product Matching policy:
    // Brand + Name + Volume + Bond/Customs Status
    productKey: buildProductKey(brand, productName, volume, bond),
  };

  if (problems.length) {
    exceptions.push({ ...record, exceptionReason: problems.join('; ') });
  } else {
    offers.push(record);
  }
});

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    sourceMessageId: item.sourceMessageId,
    fromAddress: item.fromAddress,
    supplierRecordId: item.supplierRecordId || null,
    // Carried through explicitly. 04 reads both, and this node sits between the
    // supplier lookup and 04 on all three ingestion paths — dropping them here
    // silently costs every offer its supplier-specific validity (falling back to
    // 14 days) and leaves the supplier off the internal Offer Name.
    supplierName: item.supplierName || null,
    supplierValidityDays: item.supplierValidityDays ?? null,
    // Drives auto-approval of the PUBLIC LISTING in 04. Not the send approval,
    // which no automated path writes.
    supplierTrust: item.supplierTrust || null,
    profileId: item.profileId || null,
    fingerprint: item.fingerprint,
    parsedCount: offers.length,
    exceptionCount: exceptions.length,
    offers,
    exceptions,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a number written by any European or Anglophone supplier.
 * The dangerous case is "1,234" — either 1234 or 1.234 depending on locale.
 * Rule: when both separators appear, the rightmost is the decimal point.
 * When only a comma appears with exactly 3 trailing digits, it is ambiguous
 * and is flagged rather than guessed, because guessing wrong is a 1000x
 * price error that would reach a client.
 */
function parseNumber(raw) {
  if (raw === null || raw === undefined) return { value: null, ambiguous: false };
  let s = String(raw).trim();
  if (!s) return { value: null, ambiguous: false };

  // Longest form first: stripping "eur" out of "Euro" would leave a stray "o"
  // and the letter check below would then reject an otherwise valid price.
  // Premium Brands writes a literal "Euro" column, so this is not hypothetical
  // — it only escaped notice because that sheet keeps it in its own column.
  s = s.replace(/euros?|dollars?|pounds?|usd|gbp|aed|sgd|eur|[€$£\s]/gi, '').trim();
  if (!s) return { value: null, ambiguous: false };

  // Anything with letters left is prose, not a price — a comment column such as
  // "200 MORE 31ST JULY" or "750 DUE 31ST JULY". Stripping to digits would yield
  // 20031 and 75031 and quote them as prices, so reject outright. This is the
  // main defence when a column map is misaligned against a shifted section.
  if (/[a-z]/i.test(s)) return { value: null, ambiguous: false };

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');
  let ambiguous = false;

  if (hasDot && hasComma) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (hasComma) {
    const after = s.split(',')[1] ?? '';
    if (s.split(',').length > 2) s = s.replace(/,/g, '');       // 1,234,567
    else if (after.length === 3) ambiguous = true;               // 1,234 — unresolvable
    else s = s.replace(',', '.');                                // 12,50
    if (ambiguous) s = s.replace(',', '.');                      // best guess, flagged
  }

  const cleaned = s.replace(/[^0-9.\-]/g, '');
  // Text like "n/a", "TBC" or "POA" strips down to nothing, and Number('') is 0
  // — which would price the row at zero. Reject rather than return a free product.
  if (!/\d/.test(cleaned)) return { value: null, ambiguous: false };

  const n = Number(cleaned);
  return Number.isFinite(n) ? { value: n, ambiguous } : { value: null, ambiguous: false };
}

/**
 * Read a price cell that carries its own currency and per-unit basis.
 *
 * Spreadsheets keep these in separate columns, so the profile can state them
 * once. Email offers write them inline, and the BASIS VARIES ROW BY ROW —
 * one real offer lists "Euro 2,5/btl" directly above "Euro 48,7/cs". Taking
 * the basis from the profile there would be a 6-12x error on half the rows.
 *
 * Returns { value, currency, basis } with currency and basis null when the
 * cell does not state them, so the profile default still applies.
 */
function parsePriceCell(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return { value: null, currency: null, basis: null, ambiguous: false };

  let currency = null;
  if (/€|\beur(o|os)?\b/i.test(s)) currency = 'EUR';
  else if (/£|\bgbp\b|\bpounds?\b/i.test(s)) currency = 'GBP';
  else if (/\$|\busd\b|\bdollars?\b/i.test(s)) currency = 'USD';
  else if (/\baed\b/i.test(s)) currency = 'AED';
  else if (/\bsgd\b/i.test(s)) currency = 'SGD';

  // Trailing "/btl", "/cs", "/case", "/pc" and friends.
  let basis = null;
  const m = s.match(/\/\s*(btl|bottle|cs|case|ctn|carton|pc|pcs|piece|pack|can|jar|unit)\b/i);
  if (m) {
    const k = m[1].toLowerCase();
    if (/^(cs|case|ctn|carton)$/.test(k)) basis = 'Per Case';
    else if (/^(btl|bottle)$/.test(k)) basis = 'Per Bottle';
    else if (/^(pc|pcs|piece|unit)$/.test(k)) basis = 'Per Piece';
    else if (k === 'pack') basis = 'Per Pack';
    else if (k === 'can') basis = 'Per Can';
    else if (k === 'jar') basis = 'Per Jar';
  }

  // Strip the basis suffix before reading the number, or "/btl" leaves letters
  // behind and the prose guard rejects a perfectly good price.
  const numeric = parseNumber(s.replace(/\/\s*[a-z]+\b/gi, ''));

  return { value: numeric.value, currency, basis, ambiguous: numeric.ambiguous };
}

/**
 * Read a trade pack notation into its parts.
 *
 * Four notations appear across real supplier emails:
 *   "6/70cl"          6 bottles x 70cl
 *   "120x5cl"         120 miniatures x 5cl
 *   "12/1000/40"      12 x 1000(ml) x 40% abv
 *   "20 x 250g"       20 units x 250g   (weight, not volume)
 *
 * THE MIDDLE NUMBER'S UNIT IS AMBIGUOUS in the bare "12/1000/40" form: 1000
 * means millilitres, while "6/100/35" means 100 CENTILITRES — both are 1 litre.
 * Resolved by magnitude, since 1000cl would be a ten-litre bottle and 100ml
 * would be a miniature sold by the case of six. The cut-off sits at 200.
 */
function parsePack(raw) {
  const s = String(raw ?? '').trim();
  const out = { pcsCase: null, volumeMl: null, abv: null, weightG: null };
  if (!s) return out;

  // Weight-based: "20 x 250g"
  let m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(g|gr|gram|kg)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    const n = Number(m[2].replace(',', '.'));
    out.weightG = /^kg$/i.test(m[3]) ? n * 1000 : n;
    return out;
  }

  // Explicit volume unit: "6/70cl", "120x5cl", "24/20/13.5%"
  m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    out.volumeMl = parseVolume(`${m[2]}${m[3]}`);
    const abv = s.match(/(\d+(?:[.,]\d+)?)\s*%/);
    if (abv) out.abv = Number(abv[1].replace(',', '.'));
    return out;
  }

  // Bare numeric triple: "12/1000/40", "6/100/35"
  m = s.match(/(\d+)\s*\/\s*(\d+(?:[.,]\d+)?)\s*(?:\/\s*(\d+(?:[.,]\d+)?))?/);
  if (m) {
    out.pcsCase = Number(m[1]);
    const mid = Number(m[2].replace(',', '.'));
    out.volumeMl = mid >= 200 ? Math.round(mid) : Math.round(mid * 10);
    if (m[3]) {
      const a = Number(m[3].replace(',', '.'));
      if (a > 0 && a <= 100) out.abv = a;
    }
  }
  return out;
}

/**
 * Normalise any volume expression to millilitres.
 *
 * `unitHint` comes from the Sheet Profile and is what the column means when the
 * cell carries a bare number. This is not optional detail: one supplier's
 * "content" column reads 70 for a 70cl bottle while another's "ML/BTL" reads
 * 1000 for the same size of bottle. Guessing from magnitude alone turns a 70cl
 * bottle into 70ml.
 */
function parseVolume(raw, unitHint) {
  const s = String(raw ?? '').toLowerCase();
  if (!s) return null;

  let m = s.match(/(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr|litre|liter|cc)\b/);
  if (!m) {
    const bare = parseNumber(s).value;
    if (bare === null) return null;

    const factor = VOLUME_UNIT_FACTOR[String(unitHint || '').toLowerCase()];
    if (factor) return Math.round(bare * factor);

    // No hint: a bare number is millilitres unless it is implausibly small,
    // in which case it is almost certainly litres.
    return bare > 0 && bare < 10 ? Math.round(bare * 1000) : Math.round(bare);
  }

  const n = Number(m[1].replace(',', '.'));
  switch (m[2]) {
    case 'ml': case 'cc': return Math.round(n);
    case 'cl': return Math.round(n * 10);
    case 'dl': return Math.round(n * 100);
    default: return Math.round(n * 1000); // l / ltr / litre / liter
  }
}

/**
 * Airtable stores stock in CASES, so every profile is normalised to cases
 * regardless of what its source column holds — the unit must be consistent
 * across suppliers or the numbers cannot be compared to each other.
 *
 * `stockUnit` is declared per profile: FMCG lists quote stock in pieces
 * (Rexona "Quantity" 18046, ROEM "Stock / pcs" 520), drinks lists in cases.
 *
 * Floored, because a part case is not sellable. Returns null when the source is
 * in pieces but the pack size is unknown — an unconverted piece count sitting
 * in a field labelled "cases" reads as far more stock than exists.
 */
function toCases(value, pcsCase, stockUnit) {
  if (value === null || value === undefined) return null;
  if (String(stockUnit || '').toLowerCase() !== 'pcs') return value;
  if (!pcsCase || pcsCase <= 0) return null;
  return Math.floor(value / pcsCase);
}

function parseAbv(raw) {
  const s = String(raw ?? '');
  const m = s.match(/(\d+(?:[.,]\d+)?)\s*%/) || s.match(/^(\d+(?:[.,]\d+)?)$/);
  if (!m) return null;
  const n = Number(m[1].replace(',', '.'));
  return n > 0 && n <= 100 ? n : null;
}

/**
 * Dates arrive as JS Date (cellDates), Excel serial numbers, or text.
 * Text is read day-first — these are European supplier sheets — but a value
 * that can only be month-first (e.g. 03/25/2026) is still handled.
 */
function parseDate(raw) {
  if (!raw) return null;
  if (raw instanceof Date && !isNaN(raw)) return raw.toISOString().slice(0, 10);

  const s = String(raw).trim();
  if (!s) return null;

  if (/^\d{5}$/.test(s)) {
    const ms = (Number(s) - 25569) * 86400 * 1000; // Excel epoch → Unix
    return new Date(ms).toISOString().slice(0, 10);
  }

  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;

  // "Feb 2027" / "February 2027" — a best-before month with no day. The first
  // of the month is the conservative reading: it expires no later than stated.
  m = s.match(/^([a-z]{3,9})\.?\s+(\d{4})$/i);
  if (m) {
    const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    const idx = months.indexOf(m[1].slice(0, 3).toLowerCase());
    if (idx >= 0) return `${m[2]}-${pad(idx + 1)}-01`;
  }

  // "04/2028" — month and year only, no day. Extremely common on WhatsApp and
  // in email bodies ("bbd 04/2028", "BBD 05/2027"). Read as the first of the
  // month for the same reason as the "Feb 2027" case above: it is the
  // conservative end of the range the supplier actually stated.
  m = s.match(/^(\d{1,2})[\/.\-](\d{4})$/);
  if (m && Number(m[1]) >= 1 && Number(m[1]) <= 12) return `${m[2]}-${pad(m[1])}-01`;

  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
  if (m) {
    let [, a, b, y] = m;
    if (y.length === 2) y = '20' + y;
    const dayFirst = Number(a) > 12 || Number(b) <= 12;
    const day = dayFirst ? a : b;
    const month = dayFirst ? b : a;
    return `${y}-${pad(month)}-${pad(day)}`;
  }

  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
}

function coerce(kind, raw) {
  const s = String(raw ?? '').trim();
  if (!s) return null;

  const exact = OPTIONS[kind].find((o) => o.toLowerCase() === s.toLowerCase());
  if (exact) return exact;

  const key = s.toLowerCase().replace(/[^a-z0-9€$£]/g, '');
  const syn = (SYNONYMS[kind] || {})[key];
  if (syn) return syn;

  for (const [k, v] of Object.entries(SYNONYMS[kind] || {})) {
    if (key.includes(k)) return v;
  }

  return OPTIONS[kind].includes('Other') ? 'Other' : null;
}

function cleanEan(raw) {
  const digits = String(raw ?? '').replace(/\D/g, '');
  return /^\d{8}$|^\d{12,14}$/.test(digits) ? digits : '';
}

/** Fallback when the sheet has no brand column: first word of the product name. */
function guessBrand(name) {
  const first = String(name).trim().split(/\s+/)[0] || '';
  return first.length > 1 ? first : '';
}

function buildProductKey(brand, name, volumeMl, bond) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(brand), n(name), volumeMl ?? '', n(bond)].join('|');
}

/**
 * n8n Code node — "Build Airtable Payload"
 * Mode: Run Once for Each Item
 *
 * Turns normalised rows into Airtable Offers records, splitting matched from
 * unmatched products.
 *
 * Two invariants this node exists to enforce:
 *
 * 1. EVERY offer carries Offer Date + Auto Expiry Days.
 *    Is Expired = IF(TODAY() > {Auto Expiry Date}, "Yes", "No"). Airtable treats
 *    a blank date as earlier than today, so an offer written without expiry data
 *    computes as expired, fails Send Eligible, and sits in the base looking
 *    healthy while never dispatching. Silent, so it is enforced here.
 *
 * 2. INGESTION NEVER SATISFIES A HUMAN APPROVAL.
 *    Since 2026-08-04 human control lives in exactly two places, and this node
 *    writes NEITHER: Listing Approved (the tick by Anil or Annika that puts an
 *    offer on offers.akay.ie) and dispatch approval (Gate 2, Anil or Annika,
 *    per specific dispatch). Otherwise a parser's reading of a price becomes a
 *    quote on the site or in a client's inbox with nobody having looked at it.
 *
 *    Offer Approval Status is a PROCESSING status (Anil, 2026-08-04): Trust
 *    Score High, Medium or Low all write Approved on ingestion; only Trust =
 *    Hold or an unknown/unresolved supplier holds the offer at Awaiting
 *    Approval. It feeds Send Eligible and the Public Listing formula but is no
 *    longer a human control point. (Replaces the 2026-07-30 High-only rule.)
 */

const FALLBACK_VALIDITY_DAYS = 14;

// Declared up here, not beside buildProductIndex which uses it: `const` does not
// hoist, and buildProductIndex is called from the top of the node body, before
// the helper block below has been evaluated. Latent until the Products lookup
// returned anything — with an empty list the loop never runs and never touches
// this — so it would have thrown on the first real file rather than in testing.
const norm = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

// Formula and lookup fields — writing to any of these errors the batch.
const READ_ONLY = new Set([
  'Sell Price', 'Pack Format', 'Is Expired', 'Auto Expiry Date', 'Send Eligible',
  'Public Listing', 'Public Product Description', 'Public Spec', 'Price Display',
  'Public Terms', 'Stock Display', 'whatsapp link',
  'Supplier Name', 'Supplier Email', 'Supplier Country',
  'Supplier Trust Level', 'Supplier Payment Terms',
]);

const item = $input.item.json;

const today = new Date().toISOString().slice(0, 10);
const validityDays = Number(item.supplierValidityDays) > 0
  ? Number(item.supplierValidityDays)
  : FALLBACK_VALIDITY_DAYS;

// An Airtable node REPLACES the items flowing through it rather than adding to
// them, so a product lookup wired in-line does not arrive as a field on this
// item. Reading the node by name is the reliable form; the item field is kept
// as a fallback for the case where an upstream Code node did merge it in.
// Without this the index is empty, every product "fails" to match and a whole
// file lands in review looking like a catalogue problem.
const productIndex = buildProductIndex(
  item.productLookup || nodeRecords('Fetch Products')
);

// Trust-driven approval on ingestion (Anil, 2026-08-04): High, Medium AND Low
// all auto-approve. Only Trust = Hold, or an unknown/unresolved supplier
// (blank trust), holds the offer. See the approval block below.
const trustLevel = String(item.supplierTrust || '').toLowerCase();
const autoApproved = ['high', 'medium', 'low'].includes(trustLevel);

const toCreate = [];
const toReview = [];
const productsToCreate = [];
const seenNewKeys = new Set();

for (const offer of item.offers || []) {
  const productId = productIndex.get(offer.productKey) || null;

  const fields = {
    'Offer Name': buildOfferName(offer, item),
    'Status': 'Live',
    'Offer Date': today,
    'Auto Expiry Days': validityDays,   // invariant 1

    'Brand': offer.brand || '',
    'Product Name': offer.productName,
    'Variant': offer.variant || '',
    'Volume ML': offer.volumeMl,
    'PCS/Case': offer.pcsCase,
    'Unit Type': offer.unitType,
    'ABV': offer.abv,
    'Origin Country': offer.originCountry || '',
    'Bond/Customs Status': offer.bondStatus,
    'Buy Price': offer.buyPrice,
    'Currency': offer.currency,
    'Price Type': offer.priceType,
    'Stock Cases': offer.stockCases,
    'Weight KG': offer.weightKg,
    'Cases per Pallet': offer.casesPerPallet,
    'Pieces per Pallet': offer.piecesPerPallet,
    'Language': offer.language || '',
    'MOQ': offer.moq || '',
    'Lead Time': offer.leadTime || '',
    'EAN Unit': offer.eanUnit || '',
    'EAN Case': offer.eanCase || '',
    'BBD': offer.bbd,
    'Incoterm': offer.incoterm,
    'Warehouse': offer.warehouse,

    'Source Sheet': offer.sourceSheet,
    'Source Message ID': offer.sourceMessageId || '',
    'Notes': `Ingested from ${offer.sourceSheet} row ${offer.sheetRow} on ${today}.`,
  };

  if (offer.category) fields['Category'] = offer.category;
  if (item.supplierRecordId) fields['Supplier'] = [item.supplierRecordId];

  // Price Level gates dispatch: Send Eligible requires Sharp or Normal, and a
  // BLANK value fails it as hard as High does. Left unset it silently parked
  // 1,232 of 1,728 live offers. Normal is the neutral reading; Sharp and High
  // are the deliberate calls a trader makes afterwards.
  fields['Price Level'] = 'Normal';

  // ── Trust-driven processing approval (Anil, 2026-08-04) ───────────────────
  // Offer Approval Status is a PROCESSING status: Approved for supplier Trust
  // High/Medium/Low, Awaiting Approval only for Trust = Hold or an unresolved
  // supplier. It is NOT a human control point. The human approvals live
  // elsewhere and are NEVER written by ingestion: Listing Approved (website
  // tick, Anil or Annika) and Gate 2 dispatch approval (Anil or Annika). So an
  // auto-approved offer still cannot reach the public site or a client inbox
  // without a person acting.
  fields['Offer Approval Status'] = autoApproved ? 'Approved' : 'Awaiting Approval';
  if (!autoApproved) {
    fields['Notes'] += ` HELD at Awaiting Approval: supplier trust is ${item.supplierTrust || 'unknown/unresolved'} — only Hold or unknown suppliers hold since 2026-08-04.`;
  }

  // A product we have not seen is created rather than parked. Near-duplicate
  // catalogue entries are a tidy-up job; 1,103 live offers with no product link
  // was a stoppage. New records are flagged Needs Review so the duplicates stay
  // findable, and the offer links by Product Key — Airtable resolves a link
  // field written as its primary-field value when the node has typecast on.
  if (productId) {
    fields['Products'] = [productId];
  } else {
    fields['Products'] = [offer.productKey];
    if (!seenNewKeys.has(offer.productKey)) {
      seenNewKeys.add(offer.productKey);
      productsToCreate.push({ fields: stripEmpty({
        'Product Key': offer.productKey,
        'Brand': offer.brand || '',
        'Product Name': offer.productName,
        'Variant': offer.variant || '',
        'Category': offer.category,
        'Volume ML': offer.volumeMl,
        'PCS/Case': offer.pcsCase,
        'Unit Type': offer.unitType,
        'ABV': offer.abv,
        'Origin Country': offer.originCountry || '',
        'Bond/Customs Status': offer.bondStatus,
        'EAN Unit': offer.eanUnit || '',
        'EAN Case': offer.eanCase || '',
        'Status': 'Needs Review',
        'Notes': `Created automatically from ${offer.sourceSheet} on ${today}. `
               + 'Check it is not a duplicate of an existing product spelled differently.',
      }) });
    }
  }

  toCreate.push({ fields: stripEmpty(fields) });
}

const exceptions = (item.exceptions || []).map((e) => ({
  sheetRow: e.sheetRow,
  productName: e.productName,
  reason: e.exceptionReason,
  sourceSheet: e.sourceSheet,
}));

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    supplierRecordId: item.supplierRecordId,
    createCount: toCreate.length,
    reviewCount: toReview.length,
    newProductCount: productsToCreate.length,
    exceptionCount: exceptions.length,
    toCreate,
    toReview,
    productsToCreate,
    exceptions,
    summary:
      `${item.fileName} :: ${item.sheetName} — ` +
      `${toCreate.length} offers, ${productsToCreate.length} new products, ` +
      `${exceptions.length} bad rows`,
  },
};

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Records from a named upstream node. Returns [] rather than throwing when the
 * node is absent, so the same file works in a workflow that does not have it.
 */
function nodeRecords(name) {
  try {
    return $(name).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
}

function buildProductIndex(products) {
  const index = new Map();
  for (const p of products) {
    const f = p.fields || p;
    const key = [
      norm(f['Brand']),
      norm(f['Product Name']),
      f['Volume ML'] ?? '',
      norm(f['Bond/Customs Status']),
    ].join('|');
    if (!index.has(key)) index.set(key, p.id);
  }
  return index;
}

/**
 * Offer Name is the primary field and is explicitly internal — it may carry the
 * supplier name. Public display uses Public Product Description instead.
 */
function buildOfferName(offer, ctx) {
  const parts = [offer.brand, offer.productName, offer.variant].filter(Boolean);
  const spec = offer.volumeMl ? `${offer.volumeMl}ml` : '';
  const supplier = ctx.supplierName ? ` - ${ctx.supplierName}` : '';
  return `${parts.join(' ')}${spec ? ' ' + spec : ''}${supplier} ${new Date().toISOString().slice(0, 10)}`.trim();
}

/** Airtable rejects null on some field types; omit rather than send empties. */
function stripEmpty(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields)) {
    if (READ_ONLY.has(k)) continue;
    if (v === null || v === undefined || v === '') continue;
    out[k] = v;
  }
  return out;
}

/**
 * n8n Code node — "Offers to Create"
 * Mode: Run Once for All Items
 *
 * Sits between "Create Products" and "Create Offers" and emits one item per
 * offer record.
 *
 * It exists because of an ordering constraint, not because there is any work to
 * do here. An offer whose product is new links to it by Product Key, and that
 * link only resolves once the Product row exists — so "Create Products" has to
 * run first. But an Airtable node REPLACES the items flowing through it, so by
 * the time the newly created products come out the other side, the offer
 * payloads are gone. This reaches back to the payload builder by name and puts
 * them back on the wire.
 *
 * "Create Products" is set to always output data, so a batch where every
 * product already existed still reaches this node instead of ending the branch.
 */

// Emitted FLAT, not wrapped in { fields: ... }. The Airtable node's
// "Map Automatically" mode reads the item's top-level keys as column names, so
// a nested wrapper would be written as a single column called "fields".
const offers = [];

for (const item of $('Build Airtable Payload').all()) {
  for (const record of item.json.toCreate || []) {
    offers.push({ json: record.fields || record });
  }
}

return offers;

/**
 * n8n Code node — "Route to Review"
 * Mode: Run Once for Each Item
 *
 * The hand-off point. Every email this pipeline cannot parse ends up here with
 * a plain-English reason, ready for a person to map or key in by hand.
 *
 * At 5-10 offers a day with someone available to handle the remainder, an
 * unparsed email is a hand-off, not a failure. What matters is that the reason
 * is specific enough to act on without reopening the original — "no profile"
 * is useless, "no profile for cse.ltd@cytanet.com.cy" tells you exactly what
 * to create.
 *
 * Nothing here deletes, hides or alters the email.
 */

const item = $input.item.json;

const sender = item.fromAddress || item.envelopeFrom || '(unknown sender)';
const subject = item.subject || '(no subject)';

let category;
let reason;
let action;

if (item.skipReason && /Spreadsheet attached/i.test(item.skipReason)) {
  // Not a failure at all — the Excel workflow owns this one.
  category = 'Handled elsewhere';
  reason = item.skipReason;
  action = 'None. The Excel workflow ingests this email.';

} else if (item.skipIngestion) {
  category = 'Skipped on purpose';
  reason = item.skipReason || 'Supplier is gated out of ingestion';
  action = 'None, unless the commercial position has changed — untick Skip Offer Ingestion, or change the supplier Status.';

} else if (item.blocksFound === 0) {
  category = 'Nothing to parse';
  reason = item.exceptionReason || 'No table or label:value block found in the body';
  action = 'Read it. If it is an offer, it is in a shape the parser does not yet handle — key it in, or send it over so the shape can be added.';

} else if (item.profileFound === false && /references labels absent/i.test(item.exceptionReason || '')) {
  category = 'Profile no longer fits';
  reason = item.exceptionReason;
  action = 'The supplier changed their layout. Update the Column Map on their Sheet Profile.';

} else if (item.profileFound === false) {
  category = 'No profile for this sender';
  reason = item.exceptionReason || `No email profile matches ${sender}`;
  action = `Key this one in, then create a Sheet Profile with Sender Match = ${domainOf(sender) || sender} so the next one parses automatically.`;

} else {
  category = 'Unclassified';
  reason = item.exceptionReason || 'Could not be parsed, reason not recorded';
  action = 'Read it and decide.';
}

return {
  json: {
    ...item,
    reviewCategory: category,
    reviewReason: reason,
    reviewAction: action,
    reviewSender: sender,
    reviewSubject: subject,
    // Single line for the execution log, so a skim of recent runs shows what
    // is being handed off and why without opening each one.
    reviewSummary: `[${category}] ${subject} — from ${sender}. ${reason}`,
    // Carried explicitly: the label step needs it, and on the no-blocks path
    // the earlier nodes may not have populated the usual fields.
    threadId: item.threadId || null,
  },
};

function domainOf(address) {
  const m = String(address).match(/@([^\s>]+)$/);
  return m ? m[1].toLowerCase() : null;
}

// n8n Code node — "Flatten Block" (Run Once for Each Item)
// Turns the first extracted block into the headerCells + dataRows shape the
// SHARED Normalize Rows / Resolve Body Profile code expects, and stamps the
// source identifiers the email path never set.
const item = $input.item.json;
const blocks = Array.isArray(item.blocks) ? item.blocks : [];
const first = blocks[0] || null; // first/primary block only, by design

let headerCells = [];
let dataRows = [];
if (first && Array.isArray(first.rows) && first.rows.length) {
  headerCells = first.rows[0] || [];
  dataRows = first.rows.slice(1);
}

const subject = item.subject || '(no subject)';
return {
  json: {
    ...item,
    headerCells,
    dataRows,
    fileName: `Email: ${subject}`,
    sheetName: first && first.type === 'labels' ? 'Body (labels)' : 'Body',
    sourceMessageId: item.id || item.messageId || item.sourceMessageId || null,
    blockType: first ? first.type : null,
  },
};

// n8n Code node — "Attach Profiles" (Run Once for All Items)
// The Airtable lookup above REPLACES the items on the wire, so the email items
// are read back by name and the full profile candidate list is joined onto
// every one — keeping one item per email.
const profiles = $('Find Email Profiles').all()
  .map((i) => i.json)
  .filter((p) => p && (p.id || Object.keys(p).length > 0));

return $('Flatten Block').all().map((entry) => ({
  json: { ...entry.json, profileCandidates: profiles },
}));

// n8n Code node — "Restore Offers" (Run Once for All Items)
// The Products lookup above REPLACES the items on the wire. Re-emit the
// per-email offer batches so Build Airtable Payload sees item.offers again.
// Two possible upstream sources now exist depending on which branch the email
// took: the profile-matched path (Normalize Rows) or the new-supplier LLM
// path (Attach New Supplier & Finalize Offers). Only one of the two will
// actually have execution data for any given run, so each is read defensively.
let fromProfile = [];
try { fromProfile = $('Normalize Rows').all().map((entry) => ({ json: entry.json })); } catch (e) { /* did not run this branch */ }

let fromNewSupplier = [];
try { fromNewSupplier = $('Attach New Supplier & Finalize Offers').all().map((entry) => ({ json: entry.json })); } catch (e) { /* did not run this branch */ }

return [...fromProfile, ...fromNewSupplier];

// "Emails to Mark Done" -- emits ONE item per distinct source email, carrying
// the Gmail message ID that "Mark Email Done" needs to apply the done-label.
// Two possible upstream sources of one-item-per-email data now exist: the
// profile-matched path (Normalize Rows) or the new-supplier LLM path (Attach
// New Supplier & Finalize Offers). Every Airtable node between here and
// either of those REPLACES the items on the wire, so both are read
// defensively and only whichever one actually ran contributes.
let fromProfile = [];
try { fromProfile = $('Normalize Rows').all(); } catch (e) { /* did not run this branch */ }

let fromNewSupplier = [];
try { fromNewSupplier = $('Attach New Supplier & Finalize Offers').all(); } catch (e) { /* did not run this branch */ }

const seen = new Set();
const out = [];

for (const entry of [...fromProfile, ...fromNewSupplier]) {
  const id = entry.json.sourceMessageId;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { messageId: String(id), offerCount: entry.json.parsedCount ?? null } });
}

return out;

let original;
try {
  original = $('Carry Existing Supplier Id Forward').all()[$itemIndex].json;
} catch (e) {
  original = $('New Sender or Skip?').all()[$itemIndex].json;
}
const extracted = $('LLM Extract Offers').item.json;

let supplierId = null;
let supplierName = null;
try {
  const created = $('Create New Supplier').item.json;
  supplierId = created.id;
  supplierName = created.fields ? created.fields['Supplier Name'] : created['Supplier Name'];
} catch (e) {
  supplierId = original.existingSupplierId || null;
  supplierName = original.senderDomain || original.fromAddress || null;
}

function key(o) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(o.brand), n(o.productName), o.volumeMl ?? '', n(o.bondStatus)].join('|');
}

const rawOffers = (extracted.output && extracted.output.offers) || extracted.offers || [];
const offers = rawOffers
  .filter((o) => o.productName && o.buyPrice != null && o.currency)
  .map((o, idx) => ({
    ...o,
    productKey: key(o),
    sourceSheet: 'Email (LLM extraction, new sender)',
    sourceMessageId: original.messageId || '',
    sheetRow: idx + 1,
  }));

return {
  json: {
    ...original,
    offers,
    supplierRecordId: supplierId,
    supplierName,
    supplierTrust: 'Medium',
    supplierValidityDays: 14,
  },
};

// A Sheet Profile exists for this sender WITH a real Column Map, but the
// email still reached the no-profile branch -- a data inconsistency worth a
// human look, not something safe to auto-fix.
const original = $json;
const existing = original.profileSearchResult;
return {
  json: {
    ...original,
    exceptionReason: `A working Sheet Profile ("${existing && existing.fields ? existing.fields['Profile Name'] : ''}") already exists for ${original.fromAddress}, but this email did not match it -- check Sender Match spelling/case and the Column Map's header labels rather than creating a duplicate.`,
  },
};

// A Supplier with this email may already exist even though no Email-type
// Sheet Profile matched -- e.g. a supplier we already trade with via
// Spreadsheet-type profiles, now also emailing offers directly in the
// message body for the first time. Not a duplicate case: just needs a new
// Email-type profile alongside their existing one.
// IMPORTANT: $input.item.json here is the SUPPLIER search result (or a
// synthetic {} via alwaysOutputData), not the original email -- spreading it
// directly would overwrite fromAddress/subject/blocks/prose with Supplier
// fields. Read the original email fields from the incoming item's own
// carried-forward state instead (merged in upstream by 'Merge Original
// Fields Back'), which flowed through 'Has Working Column Map?' unchanged.
const supplierSearchResult = $input.item.json;
const original = $('Merge Original Fields Back').all()[$itemIndex].json;
const existingSupplierId = supplierSearchResult && supplierSearchResult.id ? supplierSearchResult.id : null;
return {
  json: {
    ...original,
    existingSupplierId,
    existingProfileId: null,
  },
};

// 'Search Existing Sheet Profile by Sender' replaces the item with the
// Airtable search result (or a synthetic {} via alwaysOutputData). Re-attach
// the original email fields by INDEX rather than paired-item lookup --
// alwaysOutputData's synthetic items break n8n's normal item-pairing
// resolution ('Multiple matches found'), so $('Node').item is unsafe here.
// From this point on, everything downstream reads fields directly off $json
// instead of reaching back to named nodes, which sidesteps the ambiguity
// entirely for the rest of the chain.
const searchResult = $input.item.json;
const original = $('New Sender or Skip?').all()[$itemIndex].json;
return {
  json: {
    ...original,
    profileSearchResult: searchResult,
  },
};
